    -- =====================
    ["btn_bar_uniformize"]            = "Copiar el aspecto de esta barra a todas las barras",
    ["info_bar_uniformize"]           = "Copia el aspecto (tamaño, espaciado, columnas, transparencia, escala, desvanecido, textos…) a todas las demás barras. La posición y el estado de activación de cada barra se conservan.",
    ["opt_bar_hotkey_size"]           = "Tamaño de fuente de la tecla rápida",
    ["popup_ab_uniformize"]           = "¿Copiar el aspecto de la barra «%s» a todas las demás barras?",
    ["info_cb_anchor_uf"]             = "Esta barra de lanzamiento se ancla a su marco de unidad correspondiente (por lo que aparece en el marco de objetivo/foco/mascota/jefe).",
    ["tab_qol_compass"]               = "Brújula",
    ["section_compass"]               = "Barra de brújula",
    ["info_compass_desc"]             = "Una barra de rumbo en la parte superior de la pantalla que muestra N/E/S/O al girar, con un marcador que apunta hacia tu misión rastreada o el punto de ruta del mapa. Solo lectura, sin taint.",
    ["info_compass_layout"]           = "Consejo: usa el modo Layout (/tm layout) para arrastrar la barra donde quieras.",
    ["opt_compass_enable"]            = "Activar barra de brújula",
    ["opt_compass_fov"]               = "Campo de visión",
    ["compass_fov_narrow"]            = "Estrecho (±45°)",
    ["compass_fov_standard"]          = "Estándar (±60°)",
    ["compass_fov_wide"]              = "Amplio (±90°)",
    ["opt_compass_width"]             = "Ancho de la barra",
    ["opt_compass_height"]            = "Altura de la barra",
    ["opt_compass_scale"]             = "Escala",
    ["opt_compass_show_heading"]      = "Mostrar lectura de rumbo (p. ej. 245° SO)",
    ["opt_compass_show_distance"]     = "Mostrar distancia en los marcadores",
    ["opt_compass_show_quest"]        = "Mostrar marcador de misión rastreada",
    ["opt_compass_show_waypoint"]     = "Mostrar marcador de punto de ruta del mapa",
    ["opt_skyride_ground_speed"]      = "Mostrar velocidad en tierra",
    ["info_skyride_ground_speed"]     = "Muestra también tu velocidad de movimiento en tierra (los indicadores de vuelo permanecen ocultos mientras no vuelas).",
    ["btn_class_reminder_preview"]    = "Vista previa",
    ["sublabel_class_reminder_coverage"] = "— Aumentos y formas seguidos —",
    ["opt_char_skin_movable"]         = "Ventana movible",
    ["info_char_skin_movable"]        = "Una vez activado, arrastra la ventana de Personaje para moverla. Su posición se recuerda.",
    ["btn_char_skin_reset_pos"]       = "Restablecer posición",
    ["btn_sound_test"]                = "▶ Reproducir este sonido",
    ["opt_auras_max_width"]           = "Ancho máximo (ajuste de línea)",

    -- 3.2.0
    ["wn_320_gsearch"] = "Ventana de configuración: la búsqueda de la barra lateral ahora es global — encuentra opciones coincidentes en todas las categorías y pestañas, no solo en la página visible, y al hacer clic en un resultado se salta directamente a él con un destello de resaltado.",
    ["wn_320_panelcache"] = "Ventana de configuración: cambiar entre pestañas de categoría ahora es instantáneo después de la primera visita — los paneles se almacenan en caché en lugar de reconstruirse cada vez.",
    ["wn_320_configlocale"] = "Ventana de configuración: todas las etiquetas en francés codificadas de forma fija que quedaban en los paneles de ajustes ahora son totalmente traducibles.",
    ["cfg_tab_cdforge"]           = "Cooldowns",

    -- 3.2.1
    ["wn_321_cdf_intro"] = "Nuevo — CooldownForge: crea barras de cooldown personalizadas por clase, siguiendo hechizos, objetos, preajustes (pociones, piedra de sanación...), abalorios o tu habilidad racial, desde la nueva pestaña Cooldowns (categoría Combate).",
    ["wn_321_cdf_movers_io"] = "Las barras de CooldownForge ahora se pueden arrastrar con el gestor de movimiento unificado, y compartir entre personajes mediante una cadena de importación/exportación por clase.",

    -- 3.2.2
    ["wn_322_studio_intro"] = "Nuevo — Cooldown Studio: un editor a pantalla completa dedicado a las barras de CooldownForge, con pestañas por barra de Disposición/Estilo/Hechizos/Visibilidad/Compartir, accesible desde la pestaña Cooldowns.",
    ["wn_322_studio_fix"] = "Cooldown Studio: corregido que la ventana no siempre se mostraba por encima de otras ventanas, y que sus widgets no siempre heredaban el color de acento correcto.",
    ["wn_322_studio_visibility"] = "Cooldown Studio: añadida visibilidad condicional por barra — muestra u oculta una barra según el combate, la instancia, el grupo o la banda, mediante sencillos menús Indiferente/Sí/No en la pestaña Visibilidad.",
    ["wn_322_studio_finestyle"] = "Cooldown Studio: añadidos ajustes de estilo finos en la pestaña Estilo — opacidad, color/grosor del borde, un color de temporizador personalizado y un interruptor de sombra proyectada.",
    ["wn_322_forge_internal"] = "Interno: se extrajo la maquinaria compartida de CooldownForge y Cooldown Studio a una nueva biblioteca interna Forge, sentando las bases para futuros módulos de edición profunda — sin cambios visibles para el usuario.",
    ["wn_322_studio_fixes2"] = "Cooldown Studio: corregido que los botones de la barra lateral (Nueva/Duplicar/Renombrar/Eliminar/plantillas) a veces no respondieran a los clics y desbordaran su fila, corregido que Escape cerrara la ventana provocando un error de corrupción (taint), y corregido que la pestaña seleccionada se reiniciara en lugar de recordarse al cambiar de barra.",
    ["wn_322_studio_talents"] = "Cooldown Studio: la biblioteca de hechizos ahora también incluye tus talentos activos y talentos heroicos, no solo los hechizos del grimorio, para que también puedas seguirlos en las barras de cooldown.",
    ["wn_322_talent_scan_fix"] = "Cooldown Studio: corregido que el escaneo de talentos/talentos heroicos de la biblioteca no encontrara nada en el juego — ahora solo se consideran los talentos realmente elegidos, usando el campo de API correcto para leer tu elección seleccionada.",
    ["wn_322_diag_taintown"] = "Diagnóstico: corregidos informes fantasma de ADDON_ACTION_FORBIDDEN (UseToy, SetNote...) atribuidos a addons al azar — Diagnóstico ahora toma posesión exclusiva de los eventos de corrupción (taint) en lugar de dejar que el manejo propio de Blizzard los vuelva a propagar.",
    ["wn_322_actionbars_discover"] = "Barras de acción: el texto informativo de la pestaña Gestión de barras ahora también menciona que desplegar una barra revela sus controles de tamaño de botón y escala, haciendo que esa opción sea más fácil de encontrar.",
    ["wn_322_tracker_editmode"] = "Rastreador de objetivos: corregido que el rastreador se congelara al arrastrarlo mientras el Modo de Edición nativo de Blizzard estaba activo.",
    ["wn_323_studio_preview"] = "Cooldown Studio: la pestaña Estilo ahora muestra una vista previa de iconos en vivo (mismo renderizado que las barras reales) que alterna entre listo/en cooldown, para ver los cambios de estilo al instante.",
    ["wn_323_studio_copystyle"] = "Cooldown Studio: se añadió un botón «Copiar estilo desde...» en la pestaña Estilo para copiar solo el estilo visual de otra barra sin tocar los hechizos, la posición ni la disposición.",
    ["wn_323_studio_create"] = "Cooldown Studio: «+ Nueva» ahora pide el nombre de la barra desde el principio en lugar de crear un marcador de posición que luego hay que renombrar, y las ventanas emergentes de renombrar/crear ahora aparecen de forma fiable por encima de la ventana con el campo de nombre autoenfocado.",
    ["wn_323_slider_entry"] = "Deslizadores de configuración: clic derecho en un valor para escribir un número exacto, Ctrl+clic para restablecer al valor predeterminado, con un recordatorio en la información sobre herramientas para ambos.",
    ["wn_323_petbar_editmode"] = "Barras de acción: las barras de Mascota y Formas ahora se pueden seleccionar y arrastrar en el Modo de Edición incluso cuando están ocultas en reposo (sin mascota/formas).",
    ["wn_324_studio_real_icons"] = "Cooldown Studio: la vista previa de la pestaña Estilo ahora usa iconos reales — primero los hechizos de la propia barra, luego el grimorio y los talentos de tu clase — en lugar de tres iconos de demostración fijos de clases ajenas.",
    ["wn_324_chat_contacts"] = "Chat: la barra lateral del chat incorpora un botón Contactos que abre la lista de amigos de Blizzard con un solo clic, restaurando un acceso que había desaparecido al ocultar el skin el botón social nativo.",
    ["wn_324_editbox_scrollbar"] = "Configuración: los cuadros de texto multilínea (importar/exportar, notas...) ya no muestran la barra de desplazamiento dorada de Blizzard — ahora usan la fina barra de acento del addon y admiten la rueda del ratón.",
    ["wn_325_friends_window"] = "Contactos: la ventana de amigos ahora está totalmente tematizada en lugar de ser un trabajo a medias — cuerpo oscuro y plano, borde de acento dibujado sobre la lista, título rediseñado y un simple botón de cierre de acento.",
    ["wn_325_friends_tabs"] = "Contactos: las pestañas inferiores y las subpestañas Amigos / Aliados recientes / Recluta a un amigo perdieron sus placas doradas, y ahora muestran un subrayado y una etiqueta de acento en la seleccionada.",
    ["wn_325_friends_buttons"] = "Contactos: todos los botones de la ventana (Añadir amigo, Enviar mensaje, los botones de la pestaña Quién, Convertir en banda, Info de banda, Unirse a la cola) comparten ahora un mismo estilo plano de acento que se aclara al pasar el ratón, y los dos botones de contacto se reparten equitativamente la fila inferior.",
    ["wn_325_friends_toggle"] = "Contactos: desactivar el skin en los ajustes ahora restaura el aspecto de Blizzard de inmediato, sin necesidad de recargar.",
    ["wn_325_cdf_radial"] = "CooldownForge: las barras de reutilización ahora pueden disponer sus iconos en círculo en lugar de en línea — ajusta el radio, el ángulo de inicio, la amplitud del arco y el sentido desde el nuevo modo de disposición.",
    ["wn_325_cdf_spacing"] = "CooldownForge: el espaciado de los iconos son ahora dos valores separados — a lo largo de la fila y entre filas ajustadas — y el máximo se ha elevado de 16 a 64 px.",
    ["wn_325_cdf_glow"] = "CooldownForge: el brillo ahora puede activarse según una condición a elegir — cuando el hechizo está listo, mientras una mejora está activa en ti (con un ID de mejora opcional para abalorios/talentos), o siempre — configurable por barra o por hechizo.",
    ["wn_325_cdf_hidecd"] = "CooldownForge: una barra ahora puede ocultar cada icono mientras está en reutilización, y los iconos restantes cierran el hueco; solo se reorganiza cuando cambia el conjunto de hechizos listos.",
    ["wn_326_whatsnew_stuck"] = "Novedades: cerrar esta ventana con Escape dejaba la pantalla oscurecida y el ratón muerto, y la versión sin marcar, así que volvía a aparecer en el siguiente inicio de sesión. Todas las formas de cerrarla (X, botón, Escape) pasan ahora por un único sitio que retira el oscurecimiento y recuerda la versión.",
    ["wn_326_whatsnew_escape"] = "Novedades: Escape ahora lo captura la propia ventana en lugar de pasar por UISpecialFrames de Blizzard, lo que elimina una vía de taint a través del menú del juego; el resto de teclas siguen pasando sin cambios.",
    ["wn_326_whatsnew_gates"] = "Novedades: la ventana espera ahora un momento libre — nunca sobre una cinemática, un vídeo o un combate — y se salta por completo el primer inicio de sesión de un personaje, para no recibirte en plena secuencia de introducción.",
    ["wn_326_tracker_empty"] = "Rastreador de objetivos: cuando no hay nada rastreado, ya no queda un panel oscuro cubriendo casi toda la pantalla — ahora se reduce a su cabecera, y «Ocultar si está vacío» viene activado por defecto (los perfiles existentes se actualizan una vez; si lo vuelves a desactivar, se queda así).",
    ["wn_326_tracker_drag"] = "Rastreador de objetivos: el panel puede arrastrarse hacia abajo de nuevo — la sujeción a la pantalla se aplicaba al marco sobredimensionado de Blizzard, cuyo borde inferior ya quedaba fuera de pantalla, por lo que todo movimiento hacia abajo era rechazado.",
    ["wn_326_repbar_drag"] = "Barra de reputación: corregido que la barra mostrara su borde de desbloqueo en modo Disposición pero no pudiera agarrarse — nunca tuvo el ratón activado, así que el arrastre no podía empezar.",
    -- Soportes del Cooldown Manager (Movers / modo disposición)
    ["mover_cdm"]                        = "Cooldown Manager",
    ["cdm_drag_hint"]                    = "Arrastra para mover",
    ["cdm_preview_aura"]                 = "Aura",

    ["wn_326_suite_card"] = "Config: el panel de inicio incorpora una tarjeta «Suite Tomo» que presenta TomoBoss (temporizadores de jefes con avisos hablados) — un acceso directo a sus opciones si está instalado, y si no una dirección copiable y un «No volver a mostrar» definitivo.",

    ["wn_330_cdf_unusable"] = "CooldownForge: un icono ahora puede teñirse cuando el hechizo no está en reutilización pero no se puede lanzar en ese momento — sin ira, forma incorrecta, componente ausente. Tres opciones: ningún efecto (por defecto), atenuar, o atenuar con un tinte azul cuando lo que bloquea es justamente el recurso; configurable por barra y por hechizo.",
    ["wn_330_cdf_glow_usable"] = "CooldownForge: el brillo ha ganado una condición «cuando el hechizo es utilizable» — listo *y* lanzable, para que un hechizo sin recurso deje de brillar mientras espera en lugar de invitar a una pulsación que fallaría.",
    ["wn_330_cdf_hide_unusable"] = "CooldownForge: una barra también puede ocultar por completo un icono mientras falte el recurso, junto al filtro «ocultar durante la reutilización» ya existente. Ambos son independientes y acumulables, y los iconos restantes cierran el hueco.",
    ["wn_330_cp_charged"] = "Barras de recursos: los puntos de combo sobrecargados ahora se muestran como tales — la casilla cargada se marca esté llena o no, para ver dónde está la carga antes de gastarla. El color se elige en CD & Recursos → Colores, rojo por defecto.",
    ["wn_330_colorpicker"] = "Configuración: el selector de color se abría detrás de la ventana de ajustes y de Cooldown Studio, lo que parecía que la muestra no hacía nada. Ahora se abre por encima, justo al lado de la muestra que has pulsado en vez de en el centro de la pantalla.",
    ["wn_330_locale_escapes"] = "Localización: las opciones de la Brújula mostraban códigos de escape en bruto donde debían ir los acentos — «BrxC3xBAjula», «misixC3xB3n», «Amplio (xC2xB190xC2xB0)». Esos textos usaban una sintaxis de escape que el Lua del juego no entiende y la imprimía tal cual; vuelven a leerse bien, en los seis idiomas.",
    ["wn_330_diag_filters"] = "Diagnóstico: estar inmovilizado y tratar de enviar por correo un objeto vinculado se registraban como errores en el informe. Ambos son respuestas normales del juego y ahora se filtran como el resto.",
    ["wn_330_tracker_delve_place"] = "Rastreador de objetivos: con «Ocultar si está vacío» desactivado el panel seguía ahí, pero el bloque de la expedición nunca se colocaba dentro — el caso vacío salía antes de la pasada que lo coloca. Los módulos de escenario y de expedición se colocan ahora en primer lugar, sea lo que sea que estés siguiendo además.",
    ["wn_330_tooltip_info"] = "Descripción: las descripciones de unidad llevan por fin una verdadera capa de información — rango de hermandad, objetivo actual de la unidad, puntuación Mítica+, montura, velocidad de movimiento y ubicación, además de los iconos de marcador de banda, rol y clase en la línea del nombre. Cada línea tiene su propio interruptor en Skins → Descripción.",
    ["wn_330_tooltip_inspect"] = "Descripción: pasar el ratón sobre un jugador ahora muestra su nivel de objeto equipado y su especialización. Ambos requieren inspeccionar, así que solo aparecen dentro del alcance; el nivel de objeto se colorea por la diferencia con el tuyo en vez de por umbrales de temporada que caducan en cada parche.",
    ["wn_330_tooltip_border"] = "Descripción: el borde puede tomar el color de la unidad — color de clase para un jugador, hostil / neutral / amistoso para un PNJ — y la línea de nivel se colorea según la dificultad, en rojo para un jefe o una unidad «??».",
    ["wn_330_tooltip_bar"] = "Descripción: la barra de vida está ahora oculta por defecto, ya que la capa de información la sustituye. Los perfiles existentes se actualizan una vez; desmarcar la opción devuelve la barra y se mantiene.",
    ["wn_330_pf_leader"] = "Marcos de grupo: el líder del grupo se señala ahora con una corona sobre su marco, con su propio interruptor y un deslizador de tamaño.",
    ["wn_330_stance_bar"] = "Barras de acción: las clases sin formas de cambio de aspecto acababan con una barra de posturas de diez casillas vacías, y desmarcar «mostrar espacios vacíos» hacía desaparecer la barra entera. Ahora solo aparece si realmente tienes formas, con exactamente tantos botones como formas.",
    ["wn_330_leveling_panel"] = "Barra de nivel: pasar el ratón por encima abre ahora un panel con estilo en lugar de una descripción, con nivel, PX, PX restante, progreso, descanso, PX/h, tiempo para subir, PX ganada desde el último nivel y la aportación de la última misión. Se coloca debajo de la barra cuando no hay sitio arriba.",
    ["wn_330_bags_click"] = "Bolsas: desencantar, moler o prospectar desde el skin de bolsas requería dos intentos — la pulsación consumía el cursor de objetivo y al soltar se recogía el objeto. Ahora funciona a la primera, y arrastrar no se ve afectado.",
    ["wn_330_bags_layout"] = "Bolsas: se ha eliminado la disposición «Categorías», quedan Cuadrícula combinada y Bolsas separadas. Un perfil que siguiera con ella se pasa una vez a la cuadrícula combinada.",
    ["wn_330_chat_copy"] = "Chat: el icono de copia por mensaje ponía un glifo de marcador delante de cada línea, porque su textura nunca se resolvía. La opción se ha eliminado y se limpia una vez para quien la tuviera activada.",

    ["wn_331_tooltip_secret"] = "Información: toda la capa de información de unidad añadida en 3.3.0 nunca aparecía en Midnight — ni rango de hermandad, ni objetivo, ni puntuación de Mítica+, ni montura, ni velocidad, ni ubicación, ni nivel de objeto, ni especialización, ni iconos en la línea del nombre. La capa vuelve a leer el identificador de unidad desde la información, el juego ahora lo devuelve como un valor protegido y la protección lo rechazaba: nunca se escribía nada.",
    ["wn_331_tooltip_border"] = "Información: el borde con el color de la unidad estaba apagado por lo mismo — leía el identificador con su propia protección y se rendía, así que cada unidad caía en el color de borde configurado, lo que parecía exactamente que la opción no hacía nada.",
    ["wn_331_tooltip_target"] = "Información: la línea de objetivo desaparecía para cualquier jugador cuyo nombre vuelve protegido, es decir, la mayoría. El nombre ya no se envuelve en un código de color — construir esa cadena equivale a leer el nombre — y el color pasa por los argumentos de color de la propia información. Idéntico en pantalla, y ahora funciona.",
    ["wn_331_tooltip_guards"] = "Información: las propias protecciones podían lanzar un error. Una comparaba el valor con una cadena vacía antes de comprobar si estaba protegido, de modo que fallaba justo con los valores que debía interceptar, y una veintena de comprobaciones de sí/no (¿existe la unidad?, ¿es un jugador?, ¿se puede inspeccionar?…) se comparaban sin protección. Todo se comprueba ahora en el orden correcto.",
    ["wn_331_inspect"] = "Información: el nivel de objeto y la especialización vuelven con lo demás — el motor de inspección hacía las mismas comparaciones sin proteger en cada prueba de elegibilidad, y se retiraba ante un valor protegido antes incluso de enviar una petición.",
    ["wn_330_tracker_delve"] = "Rastreador de objetivos: dentro de una expedición el rastreador no mostraba nada — ni fase, ni criterios, ni progreso. «Ocultar si está vacío» solo contaba bloques de misión, mientras que una expedición registra su progreso en el módulo de escenario, que ese recuento deja fuera a propósito, así que el panel entero quedaba oculto. Las expediciones, los escenarios y los objetivos adicionales ahora cuentan como contenido, y el panel se ajusta a su tamaño cuando están solos en pantalla.",
    ["wn_327_tracker_progressbars"] = "Rastreador de objetivos: las barras de progreso de misión (recuentos de muertes, fuerzas enemigas, criterios de escenario y de expedición) han vuelto — una barra ya no se descarta como huérfana cuando su bloque solo es accesible a través de un anclaje, sobrevive a plegar y volver a desplegar su grupo, y las que se conservan adoptan por fin el estilo del resto del rastreador.",
    ["wn_327_tracker_position"] = "Rastreador de objetivos: un rastreador movido con el Modo Edición propio de Blizzard volvía a su sitio anterior en la siguiente recarga — esa posición nunca se escribía en la base de datos del addon. Ahora se guarda al terminar la sesión de Modo Edición, y un rastreador con una escala distinta del 100 % ya no se desplaza un poco más en cada recarga.",
    ["wn_327_minimap_indicators"] = "Minimapa: el indicador de dificultad de instancia seguía visible fuera de las instancias, porque volver a anclar los indicadores nativos también los forzaba a ser visibles y anulaba la regla de Blizzard. Vuelven a seguir la visibilidad de Blizzard — y el botón de expansión ya no se queda invisible para siempre al desactivarlo y volver a activarlo.",
    ["wn_327_resourcebar_frozen"] ="Barras de recursos: la barra de poder centrada se quedaba clavada en el valor que tenía al construirse — 0 de ira, 0 de energía — en todas las especializaciones cuyo único recurso es el principal (Guerrero, Sacerdote, Mago de Fuego, Tejedor de niebla, Havoc...), mientras la ventana de unidad mostraba el valor real justo al lado. Vuelve a actualizarse como cualquier otra barra.",
    ["wn_327_profile_rename"] ="Perfiles: renombrar o duplicar un perfil no hacía absolutamente nada — la reescritura de las ventanas emergentes en 11.2 eliminó el campo del que se leía el nombre escrito. Ambas acciones vuelven a funcionar, y ahora Intro confirma igual que el botón de aceptar.",
    ["wn_327_cds_rename"] = "Cooldown Studio: la misma corrección para las ventanas «Renombrar barra» y «+ Nueva» — el nombre escrito se ignoraba, así que renombrar no hacía nada y toda barra nueva salía llamada «Nouvelle barre».",
    ["wn_327_popup_layer"] = "Ventanas emergentes: el aviso de recarga, los diálogos de importar / exportar y todas las confirmaciones de perfil se dibujaban detrás de la ventana de configuración y de Cooldown Studio, dando la impresión de que no pasaba nada. Ahora se elevan por encima de la ventana de TomoMod que esté abierta.",
    ["wn_327_profile_refresh"] = "Perfiles: crear, borrar, renombrar o duplicar un perfil ahora refresca la lista en pantalla en vez de dejar la anterior servida desde la caché de páginas.",
    ["wn_327_import_perf"] = "Perfiles: importar es notablemente más rápido — la cadena decodificada para la vista previa se reutiliza al aceptar en lugar de decodificarse una segunda vez, que era la mayor parte del tirón al pulsar Importar.",
    ["wn_327_gui_split"] = "Config: Perfiles y Diagnósticos vuelven a ser categorías independientes en la barra lateral en lugar de estar agrupadas bajo Herramientas, cada una con su icono y su descripción; los enlaces antiguos a Herramientas siguen funcionando.",

