    ["wn_300_minimap"]                    = "Botón del minimapa — acceso rápido a las funciones y ajustes de TomoMod.",
    ["wn_300_buttonbag"]                  = "Button Bag — agrupa y gestiona tus botones de acción de forma eficiente.",
    ["tab_qol_rare_alert"]                = "Alerta de raros",
    ["section_rare_alert"]                = "Alerta de raros",
    ["opt_rare_alert_enable"]             = "Activar las alertas de proximidad de raros",
    ["opt_rare_alert_sound"]              = "Reproducir un sonido de alerta",
    ["opt_rare_alert_duration"]           = "Duración del cartel (s)",
    ["btn_reset_rare_alert_pos"]          = "Restablecer la posición del cartel",
    ["rare_alert_info"]                   = "Te avisa cuando hay un PNJ raro cerca. Haz clic en el cartel para seleccionarlo, colocar el marcador de calavera y fijar un punto de ruta. Clic derecho para descartarlo. Usa /tm layout para mover el cartel.",
    ["rare_alert_tooltip"]                = "Clic izquierdo: seleccionar + calavera + punto de ruta. Clic derecho: descartar.",
    ["wn_305_rare_alert_marker"]          = "Haz clic en el cartel de un raro para seleccionarlo, colocar el marcador de calavera y fijar un punto de ruta. Sonido y duración configurables; se puede arrastrar en el modo de diseño.",
    ["wn_305_tm_fix"]                     = "Corregido — hacer clic en una alerta de raro de RareScanner ya no abre la configuración de TomoMod (se ha resuelto la colisión del comando /tm).",

    -- =====================
    -- 3.3.2 — Novedades
    -- =====================
    ["wn_332_perf_auras"] = "Rendimiento: el rastreador de auras y el estilo de beneficios ahora solo escuchan tus propios cambios de auras. Nunca actuaron sobre nadie más, pero se les despertaba por cada unidad cuyas auras cambiaban — más de veinte miembros de banda y cada placa visible, sin parar — únicamente para comprobar la unidad y descartarla. El juego los filtra ahora antes de que se ejecute nada de nuestro código.",
    ["wn_332_perf_castbar"] = "Rendimiento: lo mismo para el seguimiento de latencia de la barra de lanzamiento, que se despertaba con cada lanzamiento de cada unidad visible — un grupo de esbirros entero de habilidades — cuando solo importaban tus propios lanzamientos.",
    ["wn_332_perf_gc"] = "Rendimiento: el rastreador de auras era la mayor fuente de basura de memoria de la interfaz. Su análisis y su distribución se ejecutaban varias veces por segundo en combate y desechaban un montón de tablas temporales en cada pasada; ahora reutilizan las mismas tablas de trabajo. Nada cambia en pantalla.",
    ["wn_332_aura_order"] = "Rastreador de auras: dos auras aplicadas con el mismo lanzamiento y la misma duración podían intercambiar su posición de forma visible entre actualizaciones, porque nada decidía su orden. Ahora es estable.",
    ["wn_332_skyride_leak"] = "Vuelo dracónico: /tm skyride construía una segunda copia de la barra cada vez que se usaba. La antigua se quedaba en pantalla, ya sin conexión con nada e imposible de ocultar, porque el juego nunca recupera un marco. La barra se construye una sola vez y el comando se limita a reaplicarle tus ajustes.",
    ["wn_332_skyride_ticker"] = "Vuelo dracónico: el mismo comando dejaba además, cada vez, una actualización permanente a 4 Hz que ya no había forma de detener. Ya no se acumulan, y la actualización se detiene cuando el módulo se desactiva en lugar de consultar una barra oculta.",
    ["wn_332_tooltip_incombat"] = "Información: el nivel de objeto y la especialización desaparecían de todas las descripciones emergentes en cuanto empezaba un combate, y volvían al terminar. La comprobación de alcance con la que acababa el motor de inspección es de las que el juego se niega a responder a los addons en combate: así, cada unidad se consideraba fuera de alcance durante todo el grupo — mientras el registro de contaminación se llenaba con una llamada bloqueada por cada pasada del ratón. Ahora usa una comprobación que funciona en combate.",
    ["wn_332_tooltip_backoff"] = "Información: la comprobación de alcance de reemplazo es menos precisa (ve mucho más lejos de lo que una inspección alcanza en realidad), así que un jugador demasiado lejos para responder se recuerda y se deja en paz durante veinte segundos en lugar de consultarlo en cada descripción emergente. Solo puede haber una inspección en curso a la vez, y un jugador fuera de alcance ocupaba esa plaza una y otra vez. Una descripción emergente sin respuesta tampoco se queda ya atascada en «cargando».",
    ["wn_332_diag_nopath"] = "Diagnóstico: cargar sobre un vacío, saltar a un saliente o enviar a una mascota donde no puede caminar se registraba como un error en el informe. «No hay camino disponible» es una respuesta normal del juego, y ahora se filtra en los seis idiomas.",
    ["wn_332_locale_castbar"] = "Configuración: la casilla principal del panel Barras de lanzamiento aparecía como «Activar la barra de consumibles» en todos los idiomas — dos opciones distintas compartían la misma clave de traducción y ganaba la de consumibles. Ahora cada una tiene la suya.",
    ["wn_332_locale_translations"] = "Localización: 173 cadenas por idioma traducidas al alemán, español, italiano y portugués — ajustes avanzados y de visibilidad del gestor de reutilización, categorías de misiones del rastreador de objetivos, interfaz de chat, movedores y texturas de cursor —, además de las 49 cadenas de la interfaz de chat en francés. Recurrían en silencio al inglés en lugar de mostrar un error, así que nadie las había reportado.",
    ["wn_332_locale_search"] = "Configuración: el cuadro de búsqueda mostraba el texto en bruto «gs_no_results» en lugar de «Ninguna opción coincidente» cuando no había resultados. El mensaje ya está definido en los seis idiomas.",
    ["wn_332_package"] = "Empaquetado: la descarga ya no incluye las suites de pruebas, ejemplos, documentación generada ni archivos readme de las bibliotecas incluidas. El addon nunca cargaba nada de eso.",
    ["wn_332_companion_panel"] = "Aviso de mascota: el módulo que te avisa cuando tu mascota falta o está muerta por fin tiene un panel de ajustes, en QOL. Su activación, su tamaño, su escala, si muestra el icono, el texto o ambos, y su posición en pantalla solo podían cambiarse editando un archivo a mano.",
    ["wn_332_companion_travel"] = "Aviso de mascota: podía quedarse en pantalla, a cuatro veces su tamaño, durante todo un vuelo. Solo comprobaba si estabas volando en momentos en los que aún estabas en el suelo, y después nada podía ocultarlo. Ahora se oculta al volar, en vuelo de taxi y en vehículos — y también en montura terrestre, lo que puedes desactivar.",
    ["wn_332_companion_locale"] = "Aviso de mascota: «Falta la mascota» y «Mascota muerta» aparecían en inglés fuera cual fuera el idioma del cliente. Ambos están traducidos, igual que todo el nuevo panel.",

    -- =====================
    -- 3.3.3 — Novedades
    -- =====================
    ["wn_333_summon_stuck"] = "Marcos de grupo y de banda: el icono de invocación se quedaba en el marco hasta recargar la interfaz. Una vez que aceptas o rechazas, el juego sigue devolviendo el último estado de la invocación en lugar de borrarlo, así que el icono describía algo que había dejado de existir hacía minutos. Ahora comprueba si realmente hay una invocación en curso antes de mostrar nada.",
    ["wn_333_summon_roster"] = "Marcos de grupo y de banda: al cambiar la composición, un icono de invocación podía quedarse en un marco que ya pertenecía a otro jugador. El estado se vuelve a leer en cada cambio de composición y tras cada cambio de zona, y se actualiza junto con el resto del marco en lugar de hacerlo solo cuando el juego anuncia un cambio.",
    ["wn_333_defensives_party"] = "Marcos de grupo: ahora se muestran los tiempos de reutilización defensivos activos en cada miembro. Esto solo existía en los marcos de banda, y allí era un único icono, sin duración y sin indicar de qué se trataba.",
    ["wn_333_defensives_categories"] = "Marcos de grupo y de banda: los defensivos se dividen en externos (lanzados sobre este jugador — Corteza de hierro, Capullo de vida, Supresión del dolor), de banda (Grito de reunión, Oscuridad, Zona antimagia) y personales (Escudo divino, Bloque de hielo, Piel de corteza), cada uno con su propia opción. Cincuenta hechizos, ordenados para que los externos vayan primero, con el tiempo restante y un borde coloreado por categoría.",
    ["wn_333_defensives_defaults"] = "Marcos de grupo y de banda: por defecto solo se muestran los externos. Un defensivo de banda enciende todos los marcos a la vez — justo cuando menos se pueden leer — y los personales son constantes. Ambos se pueden activar.",
    ["wn_333_defensives_size"] = "Marcos de banda: el deslizador de tamaño de los iconos defensivos solo surtía efecto tras recargar. Ahora se aplica mientras lo arrastras.",
    ["wn_333_hots_drift"] = "Marcos de grupo y de banda: los dos conjuntos de marcos no coincidían sobre qué sanaciones periódicas mostrar. Bendición del verano, Tótem de chaparrón y Aliento envolvente aparecían en los marcos de grupo pero no en los de banda — el mismo beneficio, en el mismo jugador, visible en unos y no en otros. Ahora hay una sola lista, que cubre las seis clases sanadoras.",
    ["wn_333_dispel_border"] = "Marcos de grupo y de banda: el grosor del borde del resaltado de disipación ahora es ajustable, de 1 a 6. Crece hacia fuera, así que un borde más grueso nunca invade la barra de vida, y el valor por defecto se ve exactamente como antes.",
    ["wn_333_stance_grid"] = "Barras de acción: con «mostrar espacios de botón vacíos» desactivado, la barra de posturas podía seguir mostrando diez casillas vacías, y se quedaban ahí hasta que cambiabas de postura. La pasada que revela los espacios vacíos mientras arrastras un hechizo también recorría las barras de posturas y de mascota, cuyos botones no son espacios de acción — así que los consideraba todos vacíos y los mostraba, mientras que la pasada que vuelve a ocultarlos omite deliberadamente esas dos barras, de modo que ya no quedaba nada que los devolviera a su sitio.",
    ["wn_333_diag_display"] = "Diagnóstico: los informes incluyen ahora tu resolución, modo de pantalla y escala de la interfaz — y señalan el caso en que la escala ha sido fijada por algo distinto de las opciones del juego. Por encima de 1200 píxeles de alto el cliente no reduce la escala lo suficiente por sí solo, de modo que las configuraciones de alta resolución acaban reescaladas a mano o por otro accesorio, y eso era invisible en un informe.",
    ["wn_333_diag_scalechange"] = "Diagnóstico: un cambio de escala o de resolución durante la sesión se registra con sus valores anterior y posterior, para que un reescalado aparezca junto a los errores que pueda haber causado. Ese reescalado se vuelve a aplicar tras cada pantalla de carga, que es justo cuando rompe cosas.",
    ["wn_333_diag_perf"] = "Diagnóstico: los informes recogen ahora la tasa de fotogramas (actual, además del mínimo, la media y el máximo de la sesión) y la latencia, y cada error capturado registra la tasa de fotogramas en el momento en que se produjo. Un error que solo aparece en un cliente con tirones es un problema de sincronización y no una función rota, y nada en un informe permitía distinguirlos.",
    ["wn_333_diag_scale_expected"] = "Diagnóstico: el informe afirmaba que tu escala de interfaz la había fijado una macro u otro accesorio en casi cualquier configuración. Cuando la opción de escala de interfaz del propio juego está desactivada, el valor con el que se comparaba no es el que el juego está usando, así que se señalaba una configuración perfectamente normal. Ahora calcula qué escala corresponde a tu resolución y tus ajustes, la imprime, y solo avisa cuando hay una diferencia real.",
    ["wn_333_diag_settle"] = "Diagnóstico: la escala que el juego aplica por su cuenta durante el inicio de sesión quedaba registrada en todos los informes como un reescalado a mitad de sesión. La captura de pantalla espera ahora cuatro segundos a que el cliente se estabilice antes de tomar una lectura, de forma que la única entrada de escala que queda en un informe es la que de verdad necesita explicación.",
    ["wn_333_diag_mode"] = "Diagnóstico: cuando el informe no consigue determinar tu modo de pantalla, ahora imprime los valores en bruto que le dio el juego en lugar de un simple signo de interrogación — esos nombres de ajuste cambian de una expansión a otra, y un «?» a secas no se podía diagnosticar sin volver a preguntarte. La pantalla completa en ventana y las ventanas maximizadas se reconocen en más casos, y las versiones de los accesorios ya no aparecen como «vv1.2.3».",
    ["wn_333_shared"] = "Interno: los marcos de grupo y de banda mantenían dos copias de las mismas 250 líneas — la lógica de invocación, la lista de sanaciones periódicas, el seguimiento de defensivos. Los tres fallos anteriores vienen de ahí: una corrección aplicada a una copia y no a la otra. Ahora comparten una única implementación.",

    -- =====================
    -- 3.4.6 — Novedades
    -- =====================

    ["wn_346_probe_secret"] = "Corrección — Los iconos de beneficio del Estudio de reutilizaciones, a los que 3.4.5 acababa de enseñar a conservar su cuenta atrás en combate, provocaban un error en el primer icono que vigilaba un beneficio. Al marcador invisible unido a cada icono se le preguntaba si estaba en pantalla, dando por hecho que esa es una pregunta sobre un elemento de la interfaz y no sobre el beneficio — y no lo es. Que un icono de aura esté en pantalla es exactamente que el beneficio esté activo, que es justo lo que el juego oculta: el sí-o-no que devolvía estaba a su vez oculto, y consultarlo era lo que fallaba. Proteger la llamada nunca pudo servir de nada: la llamada funcionaba perfectamente, y el fallo llegaba una línea después, al mirar la respuesta.",
    ["wn_346_probe_cooldown"] = "Cambio — Así que la pregunta se le hace a otra cosa. Cada icono ya tiene su propio barrido, el que el juego mueve directamente, y esa pieza pertenece a TomoMod y no al juego: el barrido aparece mientras el beneficio está activo y se retira cuando termina, y nada impide al addon leerlo. Da la misma respuesta, desde el lado de la frontera donde aún se puede leer. El marcador del propio juego se mantiene detrás como segunda opinión, ahora consultado sin riesgo, y si ninguno de los dos responde el icono simplemente no aporta nada en ese fotograma y sigue moviendo el barrido — que siempre fue la mayor parte de su cometido.",

    -- =====================
    -- 3.4.5 — Novedades
    -- =====================

    ["wn_345_class_secret"] = "Corrección — Las barras de vida lanzaban un error en cada actualización para cualquier jugador cuya clase el juego oculta ahora: 399 veces en una sola sesión en el informe que motivó esto. El parche 12.1 amplió lo que un addon no puede leer, y un valor oculto no es simplemente algo que falta: está ahí, y falla en cuanto se hace cualquier cosa con él — compararlo, buscar algo con él, unirlo a un texto o incluso preguntar si es cierto. Así que la comprobación tiene que ir antes; después no hay nada que atrapar. Dieciséis lugares de TomoMod leían cada uno la clase de una unidad y buscaban el color de la misma manera; ahora todos pasan por un mismo conjunto de utilidades que pregunta si un valor se puede leer antes de tocarlo. Cada lugar decide por sí mismo qué significa una clase desconocida, porque la respuesta correcta no es la misma en todas partes: el recordatorio de clase da por hecho que alguien podría necesitar el beneficio en lugar de saltarlo, el tinte de lanzador en las placas hostiles se deja sin aplicar en vez de adivinarlo, y la lista de llaves y TomoScore simplemente se dibujan sin color. La corona de líder de grupo es de la misma familia — quien lidera el grupo también puede estar oculto ahora, y en ese caso la corona sigue escondida, porque mostrarla sobre un jugador que quizá no sea el líder es peor que no mostrar ninguna.",
    ["wn_345_class_passthrough"] = "Nuevo — Y entonces volvieron los colores de clase. Recurrir a un color de facción cuando la clase no se puede leer es correcto, pero en una mazmorra eso es absolutamente todo el grupo: los marcos habrían tenido el color equivocado de forma permanente, no de vez en cuando. Resulta que el juego sigue coloreando una unidad por ti aunque no quiera decirte la clase: la clase entra en una de las funciones del propio juego y el color sale directamente de otra, hacia la barra, sin que el addon llegue a leer ninguna de las dos. Las barras de vida de los marcos de unidad, las placas, los marcos de grupo y los de banda toman primero esa vía y conservan sus colores de clase. Eso sí, solo funciona donde el color se aplica tal cual — cualquier cosa que necesite oscurecerlo o mezclarlo tiene que leer los números, y ahí el color de facción sigue siendo la respuesta.",
    ["wn_345_nameplate_auras"] = "Corrección — Las placas de nombre enemigas desaparecían al girar la cámara. No sus auras: la placa entera. Leer las auras de una unidad es otra de las cosas que el parche 12.1 puede rechazar ahora, y el rechazo llegaba en mitad del dibujado de la placa: todo lo que venía después — la barra de vida, el nombre, la barra de lanzamiento — sencillamente no ocurría, y la placa parecía borrada. Girar la cámara lo desencadenaba porque es lo que hace aparecer placas nuevas. Cada lectura de aura en una placa está ahora protegida por separado: un rechazo le cuesta a esa única aura su icono o su cuenta atrás, y nada más. Dos de las protecciones escritas para esto resultaron no proteger nada en absoluto, por un motivo que conviene conocer si escribes Lua: una protección colocada alrededor de una llamada no cubre otra llamada que se le pase como argumento, porque el argumento se ejecuta primero. Una de las dos rodeaba justamente la llamada que fallaba.",
    ["wn_345_aura_probe"] = "Interno — Once partes distintas de TomoMod leen las auras de una unidad: las auras de los marcos y de las placas, el resalte de disipación, la fila de sanaciones persistentes, el icono de beneficio de grupo, los iconos defensivos, el seguimiento de beneficios de CooldownForge. Cada una recorría hasta cuarenta huecos de aura de uno en uno, protegiendo cada paso, para descubrir solo al final que el juego no iba a responder nada. Ahora preguntan una sola vez, y la respuesta se recuerda durante el resto del fotograma: cuarenta marcos de grupo cuestan una pregunta en lugar de mil seiscientos pasos protegidos. La pregunta se hace a propósito por la vía más permisiva de leer un aura, de modo que un no significa que todas las demás vías ya estaban cerradas y que no se omite nada que pudiera dibujarse. De ahí salió un error real: CooldownForge vaciaba su propia lista de beneficios seguidos cada vez que se rechazaba un reescaneo, y luego no seguía nada hasta que el juego permitía leer de nuevo. Conviene decir el límite con claridad: esto lo hace más barato, no más completo. Un icono cuya lectura no obtiene nada sigue apagándose, igual que antes.",
    ["wn_345_aura_engine"] = "Nuevo — Las auras faltaban durante casi todo un combate, y nada lo indicaba: ningún error, nada en la placa ni en el marco, solo un hueco donde debería estar lo que querías ver. Todo lo demás de esta versión vuelve inofensiva una lectura de aura rechazada; nada de ello hace que el aura vuelva, porque el juego no la entrega mientras hay pelea. Así que TomoMod deja de preguntar. Ahora describe lo que quiere — estas auras, esta cantidad, colocadas así, con este aspecto — y el juego busca y ordena por su cuenta y devuelve los iconos ya hechos. Del lado de TomoMod ya nada lee un aura, así que no queda nada que rechazar. Todas las filas de auras del addon funcionan así ahora: perjuicios y beneficios de las placas, auras y beneficios de objetivo en tus marcos, iconos de sanación persistente del grupo, perjuicios y sanaciones persistentes de banda. Las filas de sanación persistente necesitaron un paso más: funcionaban reconociendo hechizos concretos, y el hechizo es justo lo que se oculta — así que la lista de hechizos a vigilar se entrega al juego por adelantado y él hace la selección. El aviso de disipación fue el más difícil de resolver, y cambia de forma al hacerlo. Era un borde de color alrededor del marco de un jugador, encendido comparando cada efecto perjudicial con lo que sabes retirar — y como ninguna de las dos cosas puede consultarse ya, solo se encendía fuera de combate, justo lo contrario de cuando un sanador lo necesita. Ahora es un icono pequeño en la esquina del marco, y el juego elige qué efecto mostrar: se le puede preguntar directamente si puedes disipar algo, y responde sin dejar que nadie lea nada. Dos cosas que conviene saber: los sangrados nunca aparecen, porque ninguna habilidad de clase los quita, y el control de multitudes queda fuera a propósito porque tiene su propia presentación. Se cazaron cuatro fallos por el camino: un error cada vez que desaparecía una placa, iconos creados en mitad del combate que salían sin tamaño y quedaban invisibles para siempre, los interruptores de mostrar perjuicios o sanaciones persistentes que dejaban de surtir efecto hasta recargar, y un deslizador de tamaño que había dejado de controlar nada.",
    ["wn_345_aura_layout"] = "Corrección — Las filas de auras dejaron de saltar de línea y crecían siempre en el mismo sentido, dijeran lo que dijeran los ajustes. Ceder la presentación al juego significaba indicarle el tamaño de un icono, y eso no incluía ni hacia dónde corre la fila ni dónde debe plegarse — ambas cosas pertenecen a la fila misma, y sencillamente nunca se transmitían. Los dos sentidos vuelven a funcionar, horizontal y vertical de forma independiente, junto con el espaciado entre iconos. En la misma línea: una fila configurada para ocho auras podía dibujar dieciseis cuando mostraba beneficios y perjuicios a la vez, ya que son dos listas distintas y cada una recibía el cupo completo. Ahora el cupo se reparte. La contrapartida es que una fila de ocho ya no puede llenarse por completo de perjuicios cuando no hay beneficios que mostrar — las dos listas no pueden prestarse sitio.",
    ["wn_345_cdf_probe"] = "Nuevo — Los iconos de beneficio del Cooldown Studio conservan su cuenta atrás en combate. El studio es la única presentación que no puede cederse al juego tal cual: pone tiempos de reutilización y beneficios en la misma fila, algo que el juego no contempla, y lo que de verdad necesita es más estrecho — ¿está activo este beneficio y cuánto queda? — justo lo que ya no se le permite mirar. Así que pregunta sin dejar que el juego dibuje: se engancha a cada icono un marcador invisible que vigila solo ese beneficio, y el juego mueve directamente el barrido del icono. Si el beneficio está activo se resuelve preguntando a ese marcador si está en pantalla, una pregunta sobre un trozo de interfaz y no sobre el beneficio. Una consecuencia que conviene saber: solo una cosa a la vez puede escribir el barrido, porque dos alternándose era la causa del parpadeo.",
    ["wn_345_dm_dropdowns"] = "Corrección — En la página de opciones del Medidor de daño, los desplegables de tema y de textura de barras se abrían con el número correcto de filas y sin texto en ninguna. El medidor etiqueta sus listas de una manera y el desplegable de TomoMod espera otra, y a diferencia de los demás controles este no tiene valor de reserva, así que cada fila se dibujaba vacía. La página del Medidor de daño también tiene ya su propio icono en el menú: compartía el de Diagnósticos, de modo que dos entradas llevaban la misma imagen.",

    -- =====================
    -- 3.4.4 — Novedades
    -- =====================

    ["wn_344_damagemeter"] = "Nuevo — TomoMod ya tiene un medidor de daño. DPS y HPS, daño recibido, daño evitable, daño infligido a los enemigos, absorciones, interrupciones, disipaciones y muertes, repartidos en Daño, Sanación y Acciones que recorres desde la cabecera, con una sesión Actual y otra Global y un cronómetro de combate. Merece la pena saber cómo funciona, porque explica lo que puede y lo que no: lee los datos de combate de la propia Blizzard en lugar de escuchar el registro de combate y sumarlo todo por su cuenta. Eso significa que no hay un muro de eventos que filtrar, y cifras idénticas a las del medidor de Blizzard porque son las mismas cifras. Un cliente que no ofrezca esos datos lo dice con claridad en vez de mostrarte una ventana vacía. Responde a /tdm y puede informar por decir, grupo, banda, hermandad, instancia, susurro, el canal que corresponda a tu grupo, o solo para ti.",
    ["wn_344_dm_windows"] = "Nuevo — Hasta cinco ventanas de medidor a la vez, cada una con su tipo, su sesión, sus columnas y su formato de números: seguir el daño y la sanación en paralelo es el caso normal, y con una sola ventana había que ir y volver durante todo el combate. Arrastra una ventana contra otra y se acoplan borde con borde: a partir de ahí se mueven juntas y comparten el borde que las une, de modo que redimensionar una redimensiona la otra, y apartar una la desengancha. Vienen nueve estilos — Tomo Dark, Tomo Neon, Minimal, Glossy, Ember, Frost, Terminal, Void y Parchment — junto con la textura de las barras, la fuente y su tamaño, la altura de las barras, el color de acento o los colores de clase, la transparencia dentro y fuera de combate, y una opción para mantener tu propia barra siempre a la vista.",
    ["wn_344_dm_breakdowns"] = "Nuevo — Una cifra en una barra no dice qué la ha producido. Haz clic izquierdo en cualquier barra para abrir sus hechizos ahí mismo, o clic derecho para darles su propia ventana: totales, impactos, críticos y tasa de crítico por hechizo. Un desglose por objetivo responde a la otra mitad — no qué lanzaste, sino sobre qué lo lanzaste — y cada pull puede leerse por separado como un segmento en lugar de solo como parte del total acumulado. Al hacer clic en un jugador de la lista de muertes se abre un resumen de lo que lo mató, que también puede abrirse solo cuando mueres tú; /tdm resetpos devuelve esa ventana al centro si ha acabado en un sitio poco práctico.",
    ["wn_344_dm_runrecap"] = "Nuevo — Un resumen al final de una mazmorra: daño, sanación, interrupciones, muertes y daño evitable recibido de todo el grupo, que se abre solo al terminar la carrera o vuelve con /tdm recap. Se va construyendo sobre la marcha en vez de leerlo todo al final, y eso no es una preferencia: justo cuando una llave termina, el juego deja de permitir que un addon lea esos valores, así que un resumen escrito de la forma evidente no podría ni siquiera ordenar al grupo. En su lugar se toma una instantánea discreta cada vez que sales de combate, unas quince veces en una llave, con un coste que no vas a notar. Lo que resulte ilegible en ese momento se deja como está en lugar de sobrescribirse, de modo que la última cifra válida de un jugador nunca se pierde.",
    ["wn_344_dm_standalone"] = "Nota — El medidor también se publica por separado como TomoDamageMeter. Si lo tienes instalado, la copia incluida en TomoMod se aparta al cargar y te lo dice una vez al iniciar sesión, en lugar de que dos medidores se disputen las mismas ventanas, ajustes y sesiones de combate. La que siempre cede es la copia incluida: instalar el addon independiente es una decisión deliberada, y las versiones de este que ya están en circulación no tienen forma de saber que deberían apartarse ellas mismas.",
    ["wn_344_cds_window"] = "Corrección — En el Cooldown Studio, la columna de botones de barras de la izquierda se dibujaba encima del botón del modo edición en la parte inferior de la ventana, y las etiquetas se salían de los botones que las contenían: «Import : Buffs suivis» era sencillamente más ancho que la casilla en la que estaba. La columna había superado el espacio reservado para ella cuando se añadieron los botones de importación, y nada en esta interfaz recorta un elemento que se desborda: simplemente se dibuja sobre lo que hay debajo. El espacio se calcula ahora a partir de lo que tiene que contener, los botones son lo bastante anchos para su propio texto, y la ventana es mayor para acomodarlo. Además deja de pedir más sitio del que tiene tu pantalla: solo se le había dicho que permaneciera en pantalla, lo que no sirve de nada con una ventana más grande que la propia pantalla — en una más pequeña, toda la columna izquierda podía quedar más allá del borde. Ahora se ajusta al espacio disponible, que es justo lo que hace que agrandarla sea seguro. AstralForge se apoya en la misma ventana y recibe el mismo trato. En el panel de inicio, la tarjeta del Cooldown Studio también ha subido junto a la de la Suite Tomo, ya que ambas llevan a otro sitio.",
    ["wn_344_changelog_popup"] = "Corrección — La página de Novedades no conseguía colocar las notas que mostraba: al desplegar una versión, sus párrafos quedaban unos encima de otros. El motivo: un bloque de texto debe medirse antes de que la ventana haya decidido su anchura, así que un párrafo destinado a ocupar seis líneas se medía como una sola, y todo lo que venía debajo se colocaba en el espacio que habría ocupado esa única línea. En lugar de enseñar a la página a medir texto, ahora entrega la versión elegida a esta misma ventana, que siempre ha sabido desplazarse. La página pasa a ser un índice: cada versión como un botón con el número de notas que contiene, cuatro por fila, de la más reciente a la más antigua — cincuenta y nueve en una sola columna suponían mucho desplazamiento para llegar a algo antiguo. La acompañan dos cosas menores. Leer una versión antigua ya no cuenta como haber leído la actual: mirar por curiosidad qué cambió en la 3.2.1 no se tragará el aviso de una actualización que aún no has visto. Y la barra de desplazamiento de esta ventana conservaba las dos flechas doradas de Blizzard en ambos extremos de una guía por lo demás verde; han desaparecido, y la barra aprovecha el espacio que ocupaban.",
    ["wn_344_dm_config"] = "Nuevo — Los ajustes del medidor son ahora una verdadera página de Medidor de daño en las opciones de TomoMod, y no un botón que te enviaba a otra ventana. El tema, la textura de las barras, la fuente y su tamaño, la altura de las barras y el acento con el color de clase; la opacidad del fondo, fuera de combate y en los paneles de detalle; ocultar los reinos, mantener tu propia barra a la vista, las descripciones en las barras, el cronómetro de combate y de qué lado se sitúa, reiniciar al entrar en una instancia, imantar las ventanas; los resúmenes automáticos de mazmorra y de muerte, y cuántas líneas envía un informe. Por debajo, esta página y la ventana propia del medidor pasan ahora por una única descripción de lo que hay que refrescar cuando cambia un ajuste — de lo contrario habría dos copias de eso, y discreparían en cuanto se editara cualquiera de las dos. Si un refresco falla, el ajuste se guarda igualmente, en lugar de mostrarte un error y revertir en silencio lo que acabas de cambiar. Las columnas, añadir ventanas y el filtrado por categoría se quedan deliberadamente en la ventana del medidor, ya que actúan sobre una ventana concreta y no sobre todo; la página lo indica y te lleva hasta allí. Esa ventana, además, se abría detrás de las opciones en vez de delante, lo que queda corregido.",
    ["wn_344_aura_secret"] = "Corrección — Las auras de los marcos de unidad provocaban una avalancha de errores en el parche 12.1 — 189 en una sola sesión en el informe que motivó esto. Antes el juego simplemente no devolvía nada cuando un addon pedía las auras de una unidad en un estado que no aprobaba; ahora rechaza la petición sin más, y ese rechazo no se estaba capturando, así que saltaba en cada evento de aura. Ya se captura, y el rechazo tiene salida: las auras se leen una a una, lo que es más lento pero es la única vía que queda, y un aura que sigue apareciendo vale más que una que produce un error. El seguimiento de beneficios de CooldownForge tenía el mismo problema por el otro lado: la actualización de auras que envía el juego puede llegar ahora completamente ilegible, y el mero hecho de comprobar si era una actualización completa bastaba para fallar, otras 38 veces en una sesión. Una actualización ilegible se trata ahora como completa y sencillamente se vuelve a leer todo, que es la única manera de estar al día cuando no se puede consultar el detalle.",

    -- =====================
    -- 3.4.3 — Novedades
    -- =====================
    ["wn_343_changelog"] = "Nuevo — Una página de Novedades en las opciones, con todas las versiones que TomoMod ha publicado. Hasta ahora las notas de versión solo aparecían en la ventana que sigue a una actualización, y esa ventana muestra únicamente la versión a la que acabas de pasar: una vez cerrada, el texto se pierde. La nueva página enumera todas las versiones, de la más reciente a la más antigua, y al hacer clic en una se abren sus notas. Lee exactamente las mismas notas que la ventana, así que no hay una segunda lista que pueda quedarse atrás.",
    ["wn_343_cdf_resync"] = "Nuevo — Cooldown Studio: una barra creada a partir del gestor de reutilización de Blizzard ya puede volver a ponerse al día con él. Esas barras eran correctas el día en que las creabas y después no tenían forma de volver: un rediseño de clase te obligaba a comparar listas a mano. Resincronizar vuelve a leer la categoría: las habilidades que Blizzard ha añadido desde entonces llegan, las que ha quitado se quitan. Todo lo que hiciste en la barra sobrevive — un hechizo que sigue en la lista conserva su entrada tal y como la ajustaste, incluidas la condición de destello, la visibilidad por especialización y los efectos por entrada — y lo que añadiste tú nunca se toca ni se elimina, haga lo que haga la lista de Blizzard. Un hechizo que habías añadido a mano y que Blizzard incorpora más tarde a la categoría sigue siendo tuyo en lugar de ser adoptado, de modo que una resincronización posterior jamás podrá borrar una entrada que creaste.",
    ["wn_343_cds_icons"] = "Cooldown Studio: la lista de lo que sigue una barra mostraba Sort 384100 — exacto y completamente inútil. Cada entrada muestra ahora su icono y su nombre, con el identificador entre paréntesis a continuación. Mientras el cliente no haya guardado el hechizo en caché seguirás viendo solo el número, que es la respuesta honesta en lugar de una línea en blanco.",
    ["wn_343_cds_scale"] = "Nuevo — Cooldown Studio: un deslizador de escala de los iconos, en las dos disposiciones. Agrandar una barra significaba mover un deslizador de anchura y luego llevar el de altura exactamente al mismo punto; ahora es un solo control. Es una vista sobre el tamaño que ya tenías y no un ajuste nuevo, así que debajo sigue habiendo un único número y nada que mantener sincronizado. Un botón devuelve los iconos a cuadrados conservando el tamaño que tenías delante en lugar de saltar al valor por defecto. En cuanto separas a propósito la anchura y la altura, el deslizador de escala se atenúa — escalar por 1,2 ya no tiene una respuesta única en ese momento — y es ese botón el que lo devuelve.",
    ["wn_343_iconsize_range"] = "Corrección — Cooldown Studio: un tamaño de icono inferior a 24 o superior a 64 parecía aceptado y no lo estaba. La barra se dibujaba con el tamaño que pedías y lo conservaba, hasta que alguna acción posterior — una resincronización, una importación, un duplicado — lo revertía en silencio, sin nada que ligara ese cambio a algo que hubieras hecho. Mientras tanto, los ajustes separados de anchura y altura aceptaban de 8 a 128, de modo que el mismo icono pequeño era alcanzable por un control y rechazado por el otro. Ahora hay un único rango, de 8 a 128, para los tres. Es más amplio que antes y no más estrecho: ninguna barra que ya tengas cambia de tamaño.",
    ["wn_343_studio_shortcut"] = "Nuevo — Un botón de Cooldown Studio en el panel de inicio, para que abrir el estudio ya no exija pasar antes por el panel de CooldownForge.",

    -- =====================
    -- 3.4.2 — Novedades
    -- =====================
    ["wn_342_astralforge"] = "Nuevo — AstralForge, un editor a pantalla completa para las piezas de un marco de unidad. Hasta ahora cada parte de un marco estaba donde TomoMod había decidido que estuviera, y lo único que se te daba era un deslizador que la empujaba unos píxeles desde ahí: mover el nombre al otro lado no era un ajuste, era un número lo bastante grande como para arrastrarlo hasta allí. Ahora arrastras cada pieza a donde quieras: qué esquina del elemento se engancha, y a qué se engancha — el marco, la barra de vida, la barra de recurso, la barra de información. Se ajusta a una rejilla pequeña, se alinea con los demás elementos al pasar junto a ellos, y manteniendo Mayús lo sueltas donde te apetezca. Los deslizadores siguen ahí para un retoque de dos píxeles, y ambos escriben lo mismo. Se abre desde las opciones de Marcos de unidad y, como el Cooldown Studio, solo se carga cuando lo pides. Lo que arrastras es una copia de vista previa, nunca un marco real: el juego protege esos durante el combate, y editarlos directamente es justo lo que provoca los problemas de interfaz que TomoMod lleva dos versiones eliminando.",
    ["wn_342_af_nameplates"] = "Nuevo — Las placas de nombre reciben el mismo editor, y para ellas es terreno completamente nuevo: salvo la marca de banda, nada en una placa tenía ajuste de posición alguno. El nombre, el valor y el porcentaje de vida, el nivel, el icono y el texto de clasificación, la barra de lanzamiento con su icono, su nombre, su temporizador y su escudo, y el icono de misión pueden colocarse cada uno donde quieras. Tu posición de la marca de banda se conserva tal cual, y todo lo demás arranca exactamente donde ya estaba. Dos cosas no son arrastrables a propósito: las auras, cuya posición se calcula a partir de su lugar en la fila en vez de fijarse, y las piezas ancladas al relleno de una barra — un tirador sobre esas afirmaría mover algo que no puede mover.",
    ["wn_342_af_props"] = "Nuevo — Opacidad, escala y un forzado del tamaño de texto, por elemento. El forzado empieza en cero, es decir «deja el tamaño que calculó el módulo», así que nada cambia hasta que tú lo digas. Solo se muestran los ajustes que una pieza concreta puede cumplir de verdad: la opacidad significa algo en un texto, la escala no, y una imagen simple no admite ninguna de las dos — obtienes los que se aplican a lo que has seleccionado en lugar de una fila fija de deslizadores de los que la mitad no hace nada.",
    ["wn_342_af_customtext"] = "Nuevo — Texto que escribes tú. Añade hasta seis textos personalizados a un marco de unidad y cuatro a una placa de nombre, escribe algo como «[name] - [level]» y colócalo como cualquier otro elemento. Las claves son nombre, nivel, clase, raza y hermandad en un marco, y nombre, nivel, clase, raza y clasificación en una placa. Merece la pena saber por qué esto no es simplemente el accesorio pegando palabras: en Midnight el juego entrega el nombre y el nivel de una unidad de una forma que un accesorio no tiene permitido leer, así que algo tan corriente como unir un nombre a un guion fallaría. Tu plantilla se convierte en un patrón, los valores pasan sin tocarse y es el propio juego quien lo ensambla todo.",
    ["wn_342_af_presets"] = "Nuevo — Ajustes de disposición guardados y cadenas para compartir. Guarda con un nombre toda la disposición de lo que estás editando — cada posición, cada opacidad y escala, cada texto propio —, vuelve a aplicarla más tarde o pásasela a alguien como una cadena que pega. Todo lo que entra se comprueba igual, sea tuyo o de un desconocido: los valores que el accesorio no reconoce se descartan, un anclaje imposible se rechaza antes de llegar al juego, y una disposición que se refiere a sí misma en bucle se rompe. Lo peor que puede describir una cadena pegada es una disposición.",
    ["wn_342_af_migration"] = "Tus marcos no se mueven. Cada posición que tenías ajustada se convierte a la nueva forma junto con el anclaje contra el que el motor la aplicaba, de modo que un perfil convertido y uno recién creado dibujan exactamente el mismo marco. Un ajuste antiguo se descarta en lugar de convertirse: un desplazamiento de auras que el motor dejó de leer en la 3.0.5. Lleva varias versiones sin efecto alguno, y convertirlo ahora movería auras que están justo donde tú las pusiste. Los contenedores de auras también dejan de guardar su posición en un segundo sitio propio: arrastrarlos en el juego, colocarlos en el editor y ajustarlos con los deslizadores escriben ahora en el mismo lugar, así que ya no pueden contradecirse.",
    ["wn_342_af_secret"] = "Corrección — Abrir AstralForge sobre una unidad que estaba realmente ahí podía dejarte una ventana vacía. La vista previa que construye se alimentaba de datos reales, y en el juego actual cualquier pieza de la interfaz cuyo contenido procede de información protegida — un valor de vida, por ejemplo — oculta también su propia posición y su tamaño a los addons. Medir eso es justamente todo el trabajo del editor: la primera medición fallaba y se llevaba la vista previa por delante. Ahora la vista previa funciona con datos inventados: un nombre inventado, un valor de vida inventado, que nada impide medir y que se ven exactamente como aquello que estás colocando. La acompañan dos salvaguardas: lo que aun así no se puede medir se queda simplemente sin tirador en lugar de detener todo lo que hay alrededor, y si la vista previa no se puede construir en absoluto, la ventana se abre igualmente con su lista de elementos, su inspector y sus ajustes guardados en vez de abrirse vacía.",
    ["wn_342_keysync_realm"] ="Mítica+: la lista de llaves del grupo salía vacía para todo el mundo de tu propio reino. Su llave se recibía y se guardaba desde el principio — simplemente no se podía volver a encontrar. Cuando el accesorio de otra persona te envía su llave, el juego la nombra como «Alice-Varimathras», sea ese tu reino o no: cada llave queda archivada bajo un nombre completo. Pero cuando TomoMod le pregunta al juego por la persona que tienes al lado en tu propio reino, recibe «Alice» sin reino, y eso no coincide con nada. Apareció con el nuevo intercambio de llaves de la 3.4.1, porque la biblioteca a la que sustituye escondía ese desajuste dentro de su propio código. Un nombre sin reino ahora se reintenta con el tuyo, así que una llave del mismo reino vuelve a encontrarse — y se hace una sola vez, allí donde se guardan las llaves, en lugar de ser algo que cada pantalla que las lee tenga que recordar.",
    ["wn_342_escape_keys"] = "Corrección — Mientras una de las ventanas propias de TomoMod estaba abierta, tus teclas no hacían nada: no podías moverte y tus habilidades no salían. Cualquier ventana que se cierre con Escape tiene que pedirle el teclado al juego, y una ventana que sostiene el teclado se queda con todas las teclas salvo que pase el resto deliberadamente — cosa que solo hacía de rebote, al recibir una tecla que no le interesaba, y nunca en combate, que es justo cuando perder las teclas sale más caro. Ahora todas las teclas pasan directamente; la ventana se queda solo con Escape, y solo fuera de combate. A eso se suma la otra mitad del problema: una ventana sostiene el teclado únicamente mientras está realmente en pantalla. Una cerrada con Escape mantenía la sujeción después, así que el problema sobrevivía a la ventana que lo había causado y la siguiente que abrías lo heredaba. Esto afecta a todas las ventanas del addon que se cierran con Escape: las opciones, el instalador, la ventana de botín, el centro de Mítica+, TomoScore, el ayudante de profesiones, el aspecto de las bolsas, la ventana de copia del chat y el Cooldown Studio.",
    ["wn_342_keysync_debug"] ="Nuevo — /tmt keysync. Muestra por qué canal va el intercambio, si estás en hermandad, todas las llaves que tiene guardadas en ese momento y, después, cada miembro de tu grupo indicando si su llave se encuentra realmente. Esa última línea es lo importante: una llave guardada pero no encontrada es un problema distinto de una llave que nunca llegó, y desde la lista del grupo las dos se ven exactamente igual — por eso el fallo anterior costó más identificarlo que corregirlo. El comando termina pidiendo sus llaves al grupo, así que ejecutarlo de nuevo un segundo después te dice si alguien ha respondido.",
    ["wn_342_cdf_viewer"] = "Nuevo — Cooldown Studio: crea una barra desde el propio gestor de reutilización de Blizzard con un clic. Tres botones — Esenciales, Utilidades y Beneficios seguidos — crean una barra ya rellenada con las habilidades que Blizzard selecciona para la especialización en la que estás, en su propio orden, y los beneficios seguidos llegan como beneficios y no como tiempos de reutilización: aparecen mientras están activos y descuentan lo que les queda. La lista se lee en el momento en que haces clic y nunca se guarda: Blizzard mantiene esas tres categorías al día a lo largo de los rediseños de clase, así que una barra importada sigue al juego en lugar de congelar una copia que sería correcta durante un parche y silenciosamente incorrecta a partir del siguiente. Donde un talento ha sustituido una habilidad por otra, es la sustituta la que acaba en la barra, para que el icono coincida con el de tu libro de hechizos. Es un punto de partida, no una atadura: lo que obtienes es una barra corriente que puedes reordenar, recortar y volver a estilizar. Y si tu cliente no tiene el gestor de reutilización, o Blizzard no selecciona nada para la especialización en la que estás, el estudio te lo dice en vez de darte una barra vacía.",

    -- =====================
    -- 3.4.1 — Novedades
    -- =====================
    ["wn_341_style"] = "Rastreador Mítica+: era la última pantalla de TomoMod con colores propios. La versión anterior alineó el marcador de fin de llave y dijo que el rastreador que ves durante la llave no encajaría hasta recibir el mismo repaso — aquí está. Ahora usa el mismo verde, el mismo texto y los mismos bordes que cualquier otro panel, sobre un fondo casi negro con un matiz menta. Viene con un ajuste de tamaño de fuente, de 0,70 a 1,60: agranda el texto sin agrandar el panel.",
    ["wn_341_segments"] = "Rastreador Mítica+: el cronómetro son ahora tres segmentos, uno por cofre, y cada uno descuenta el tiempo que queda antes de perder ese cofre. Hasta ahora el panel mostraba el tiempo transcurrido y la diferencia con el límite total, y «cuánto falta para perder el +2» era una cuenta que hacías de cabeza entre pull y pull. Los segmentos se dimensionan con los tiempos reales de cofre de la mazmorra, se leen menta, amarillo y rojo de izquierda a derecha — la ventana en curso se nombra sola por su color — y un segmento gastado se atenúa en lugar de desaparecer, para que la barra siga siendo el historial de la llave. Si prefieres leer la barra por la forma y no por el color, un ajuste pinta los tres del mismo verde.",
    ["wn_341_presets"] = "Rastreador Mítica+: un panel fijo se ha convertido en tres aspectos. Panel es lo que ya tenías. HUD quita el fondo y el bloque de cabecera y lista los objetivos como texto simple, algo más grande, en una tipografía condensada. Mínimo son tres filas y nada más — información, cronómetro, esbirros — la lista de jefes desaparece y su recuento sube a la cabecera: sigues sabiendo que vas 2 de 4 sin gastar cuatro filas en decirlo. Todo lo que fija un preajuste es además un interruptor propio: fondo, bloque de cabecera, nombre de la mazmorra, lista de jefes, disposición del cronómetro, colores de los segmentos, tamaño del texto. Cambia uno a mano y el preajuste pasa a decir «personalizado» en vez de fingir que sigues en él.",
    ["wn_341_forces"] = "Rastreador Mítica+: la barra de esbirros podía mentir en vez de admitir que no veía nada. El juego oculta cada vez más valores en combate, y la barra hacía cuentas con ellos igualmente — un recuento ilegible salía como cero, y una barra que se vacía en mitad de un pull no parece un dato que falta, parece un reinicio. Ahora conserva la última cifra que pudo leer de verdad y retrocede por etapas: recuentos exactos, luego solo el porcentaje, luego congelada. Además muestra lo que queda por matar en lugar de 730 / 1000, e indica el momento en que se completó el recuento.",
    ["wn_341_bossnames"] = "Rastreador Mítica+: los nombres de los jefes salían de una tabla escrita a mano que caduca cada temporada. Blizzard añade mazmorras y reutiliza entradas del diario entre ellas, así que una lista así está mal el día que sale el parche y nada te avisa: los nombres simplemente se degradan a «Jefe 1». Ahora los nombres se resuelven en vivo desde el juego, de tres maneras y en orden: el mapa en el que estás, luego el nombre de la mazmorra cotejado con el diario, y luego el texto en bruto del objetivo si nada más funciona. Lo que encuentra se recuerda por mazmorra: es aprendido y no escrito de antemano, así que no puede caducar.",
    ["wn_341_splits"] = "Rastreador Mítica+: no tenías nada con lo que comparar una llave. Cada llave terminada se registra ahora por mazmorra y por nivel, y en el siguiente intento cada jefe muestra cuánto vas por delante o por detrás de tu mejor marca. Los esbirros reciben el mismo trato: en cada muerte el rastreador anota dónde estaba tu mejor intento en ese momento y te enseña la diferencia. Una llave agotada también se registra — puede ser tu única referencia en esa mazmorra, y una lenta vale más que ninguna. Nada viene precargado: una tabla de «esbirros esperados en el jefe 2» incluida por un addon sería la ruta de otra persona y estaría mal el día que reequilibren la mazmorra. Un botón en las opciones borra lo registrado.",
    ["wn_341_banner"] = "Rastreador Mítica+: el final de una llave pasaba sin comentario. Ahora hay un cartel — en tiempo o agotada, el tiempo del intento, las mejoras y el margen entre paréntesis. El margen es la cifra que todo el mundo dice en voz alta al acabar una llave, y era lo único que tenías que reconstruir tú mismo a partir de un cronómetro ya detenido.",
    ["wn_341_options"] = "Rastreador Mítica+: tenía una segunda ventana de opciones propia, con los mismos ajustes que la página Mítica+ de la configuración de TomoMod — dos sitios para cambiar un mismo valor, y se separaban. Ha desaparecido: /tmt abre ahora la configuración en la página Mítica+. Todos los demás comandos /tmt siguen igual.",
    ["wn_341_legibility"] = "Rastreador Mítica+: el texto escrito encima de una barra llena era ilegible. Cada etiqueta que dibuja el rastreador lleva un contorno negro, y ese texto era casi negro él mismo, así que se disolvía en su propio contorno — las marcas de cofre del cronómetro y la etiqueta de la barra de esbirros eran manchas mientras el reloj blanco de al lado seguía nítido. Ahora son claros. Dos detalles vienen con ello: una duración negativa podía aparecer como una positiva grande, -3:40 salía como 56:20, y el primer jefe ya no repite su tiempo de muerte dos veces en la misma línea.",
    ["wn_341_cds_taint"] = "Cooldown Studio: abrirlo podía impedirte cerrar sesión, por dos vías distintas. Una línea escribía en una tabla que pertenece a Blizzard — sin cambiar su valor, pero escribir en ella basta para que el juego desconfíe después de cualquier ventana construida a partir de esa tabla, incluida la confirmación de salida. Aparte, la ventana «copiar el estilo desde» gestionaba Escape con su propia copia de un código que ya existe en otra parte del addon, y esa copia se había desviado: había perdido la comprobación de combate y devolvía las teclas al juego de una forma que impedía abrir el menú. Ambas cosas están corregidas, y la ventana usa ya la implementación común en vez de guardar una propia. Ninguna de las dos afectaba a una sesión en la que no hubieras abierto el Studio, y por eso costó tanto atribuirlas.",
    ["wn_341_keysync"] = "TomoMod se señalaba a sí mismo como origen de problemas de interfaz decenas de veces en cada combate, sin serlo. La causa era una biblioteca incluida, LibOpenRaid, que averigua si el juego oculta un valor intentando leerlo y capturando el error — la respuesta es correcta, pero el juego escribe el nombre de TomoMod en su registro en cada intento, y eso ocurre sin parar. La biblioteca ya no se distribuye. Estaba ahí por cuatro funciones de piedras angulares y nada más, mientras además sincronizaba tiempos de reutilización, equipo, talentos y durabilidad — y es esa parte la que lo provocaba todo. El intercambio de piedras angulares es ahora propio de TomoMod, en un archivo mucho más pequeño: tu piedra viene directa del juego, y el resto se comparte con tu grupo y tu hermandad, y se conserva hasta el reinicio semanal. Algo que debería funcionar por primera vez: la lista de piedras del grupo se actualiza sola cuando alguien cambia la suya — el aviso antiguo estaba conectado de una forma que la biblioteca nunca llegaba a llamar.",
    ["wn_341_buffskin"] = "El aspecto de beneficios y perjuicios se ha eliminado — la función entera, con su pestaña y sus ajustes. No puede funcionar en el juego actual: los botones que Blizzard usa para las auras ahora ocultan su propio tamaño a los addons, y poner un borde en uno provoca un error dentro del código de Blizzard, no en el de TomoMod, donde se habría podido atrapar. A eso se suma que esos botones se rehacen casi en cada parche: solo esta versión ha gastado cinco intentos persiguiéndolos. Es un mantenimiento sin final, justo en la parte de la interfaz donde la propia presentación de Blizzard ya es suficiente. Tu ventana de beneficios vuelve a la del juego, y los ajustes se borran de tus perfiles porque no hay adónde llevarlos. Si un aspecto propio para los beneficios te importa de verdad, un addon de auras dedicado es la respuesta honesta.",
    ["wn_341_auratracker"] = "El rastreador de auras se ha eliminado. CooldownForge hace el mismo trabajo y lo hace mejor, y tener dos capas peleándose por el mismo rincón de la pantalla no podía acabar de otra manera. Su pestaña, sus preajustes, su movedor y sus ajustes se van con él, y una limpieza única retira los ajustes sobrantes de tus perfiles en lugar de arrastrarlos para siempre. Si le habías añadido hechizos a mano, no se pierden en silencio: no se pueden convertir automáticamente, así que TomoMod los enumera una vez en tu próximo inicio de sesión, con sus nombres, y puedes recrear los que aún te importen en el Cooldown Studio.",
    ["wn_341_cds_reload"] = "Cooldown Studio: cerrarlo ahora puede recargar tu interfaz, y lo hace por defecto. El Studio solo se carga cuando lo pides, pero el juego no sabe descargar un addon — una recarga es lo único que lo libera, y es también lo que limpia cualquier cosa que la sesión haya podido arrastrar. El aviso espera un momento razonable: nunca en combate, nunca durante una llave, nunca dentro de una mazmorra o banda, y vuelve en cuanto sales. Puedes desactivarlo en las opciones de CooldownForge. Aparte, salir del Studio con las barras desbloqueadas las dejaba atrapadas en modo edición, con el botón de reanudar flotando en pantalla; ahora las dos formas de cerrar la ventana recogen.",

    -- =====================
    -- 3.3.6 — Novedades
    -- =====================
    ["wn_336_cdf_active"] = "CooldownForge: un buff activo se veía exactamente igual que un hechizo recargándose. Desde que un icono puede seguir un buff en vez de un tiempo de reutilización, ambos estados llegaban a la pantalla como la misma imagen simple, y la única forma de distinguirlos era leer el número encima. Dos ajustes nuevos los separan: el barrido del tiempo de reutilización y el borde pueden tomar cada uno el color de tu clase, o uno que elijas, mientras el buff seguido está activo. Los dos vienen desactivados en todas partes, así que nada de lo que ya has construido cambia, y solo se aplican a entradas que realmente siguen un buff.",
    ["wn_336_cdf_threshold"] = "CooldownForge: la cuenta atrás puede cambiar de color cuando un hechizo está a punto de volver. Fija un umbral en segundos, hasta 60, y elige el color que toma por debajo — leer un color en pleno combate es más rápido que descifrar un número. Cero lo desactiva y es lo predeterminado. Donde el juego se niega a decirle a un addon cuánto queda, que es el caso en contenido restringido, el temporizador conserva su color normal en vez de adivinar: una cuenta atrás que adivina mal sería peor que una que se queda sin cambios.",
    ["wn_336_cdf_font"] = "CooldownForge: el texto de tus iconos estaba fijado a una sola fuente. El ajuste existía en cada barra desde que salió la función y nada lo leyó nunca — la cuenta atrás, los acumulados, el nombre del hechizo y el temporizador espejo estaban todos escritos a fuego sobre la Poppins de TomoMod. Ahora puedes elegir cualquier fuente compartida por tus otros addons, optar por un contorno fino, grueso o ninguno, y dar a la cuenta atrás su propio tamaño independiente del texto de acumulados y nombre, de modo que cambiar de fuente ya no obliga a abandonar los tamaños de tu preajuste. Los dos deslizadores de tamaño van ahora de 8 a 28 píxeles en vez de 9 a 20. Sin ningún addon de fuentes compartidas instalado, la lista solo contiene Poppins y lo indica.",
    ["wn_336_cdf_glow_charges"] = "CooldownForge: el brillo puede esperar a que vuelvan todas las cargas. Un hechizo de dos o tres cargas estaba listo o no desde el punto de vista del brillo, así que una carga de tres se iluminaba igual que tres de tres. La nueva condición se deduce de la recarga misma en vez de contar — el juego oculta el número actual durante un combate, y contar es precisamente lo que allí no se puede hacer. Un hechizo sin cargas recae en la disponibilidad normal, para que la condición no sea silenciosamente inútil en la mayoría de tus entradas.",
    ["wn_336_cdf_glow_stacks"] = "CooldownForge: el brillo puede esperar a que un buff seguido alcance un número de acumulaciones, ajustable por barra y redefinible por icono. El juego no publica un máximo para un buff, así que el número lo pones tú — de 2 a 20 en una barra, hasta 99 en una entrada. Si el número de acumulaciones no se puede leer, el brillo se queda apagado en vez de dispararse por una suposición, ya que un brillo es algo sobre lo que actúas.",
    ["wn_336_escape_taint"] = "Ventanas: pulsar Escape podía dejar de abrir el menú del juego por completo, sin forma normal de salir. Ocho ventanas de TomoMod se cerraban con Escape apuntándose a una lista que Blizzard recorre desde el código de su menú, y ese código hace tres llamadas que el juego rechaza en cuanto algo ha alterado la sesión — así que el menú no se abría nunca y Escape no hacía nada. Esas ventanas gestionan ahora Escape por sí mismas y no tocan el menú del juego. El resto de teclas siguen pasando. Una consecuencia a tener en cuenta: en esas ocho ventanas Escape ya no cierra durante un combate, porque la llamada que lo permite está restringida en combate. Su botón de cerrar sí sigue funcionando.",
    ["wn_336_statusbar2"] = "Nuevo — Ocultar la barra de estado 2 de Blizzard, en QOL, Automatizaciones. La segunda barra de estado del modo edición está junto a la principal y no dentro de ella, por lo que la opción que oculta las barras de estado de Blizzard nunca llegaba hasta ella y no había ningún ajuste que lo hiciera. Se vuelve invisible y no clicable en lugar de eliminarse, y eso es lo que evita errores: la barra sigue siendo de Blizzard, así que permanece en su modo edición y allí puedes seguir moviéndola. Al desmarcar la opción vuelve tras recargar.",
    ["wn_336_ab_empty_refresh"] = "Barras de acción: con las casillas vacías ocultas, arrastrar un hechizo a una de ellas dejaba el botón en blanco. El hechizo estaba realmente ahí y se lanzaba al hacer clic, pero no se dibujaba nada encima hasta recargar — y soltar sobre una barra borraba las casillas vecinas que acababan de aparecer para el arrastre. El ocultado de casillas vacías cambió de método en la versión anterior para dejar de provocar errores en los botones de Blizzard, y el nuevo método dejaba a la barra sin enterarse de que una casilla se había llenado. Ahora se entera, incluso cuando un cambio de página o de forma altera a qué apunta un botón.",
    ["wn_336_uf_aura_growth"] = "Marcos de unidad: las auras solo crecían hacia abajo. El ajuste de dirección cubría izquierda y derecha, y la mitad vertical de la cuestión no tenía ningún ajuste — así que un marco situado en la parte baja de la pantalla mandaba su segunda fila de perjuicios fuera del borde inferior sin que nada pudiera impedirlo. Ahora hay una dirección vertical junto a la horizontal en la pestaña Auras de cada unidad, y las filas pueden apilarse hacia arriba. Hacia abajo sigue siendo el valor por defecto y nada de lo que ya tienes configurado se mueve; el marco tampoco se mueve, es el bloque de auras el que crece en el otro sentido.",
    ["wn_336_ts_palette"] = "Mythic+: la tabla de resultados de fin de mazmorra era la única pantalla de TomoMod con colores propios — un acento cian donde el resto del addon es verde, sobre un fondo azulado donde el resto es neutro. Venía de antes de su integración en TomoMod y nunca se había alineado, así que parecía la ventana de otro addon. Ahora adopta el mismo tema que todo lo demás. Dos colores se mantienen a propósito: la barra « a tiempo » y su texto conservan su propio verde, porque en un panel que ya es verde por todas partes, una marca « a tiempo » del mismo verde deja de indicar nada. El rastreador que se ve durante la llave no se ha tocado por ahora, así que los dos no coincidirán hasta que reciba el mismo tratamiento.",
    ["wn_336_cdf_talent"] = "CooldownForge: un icono puede ligarse a un talento — mostrado solo si está cogido, o solo si no lo está. La segunda mitad es tan útil como la primera: una build que deja un talento suele ganar otro en su lugar, y ahora ambos iconos pueden convivir en la misma barra con solo el pertinente en pantalla. Indicas el hechizo que concede el talento y no un número de nodo: los nodos se renumeran en cada rediseño de talentos, los hechizos no, así que la condición sobrevive a un parche. También sigue tus loadouts ahora — cambiar de build se anuncia de forma distinta a editar talentos, y solo se estaba escuchando una de las dos señales, de modo que una condición podía seguir respondiendo con la build anterior hasta que algo ajeno forzara una actualización.",

    -- =====================
    -- 3.3.5 — Novedades
    -- =====================
    ["wn_335_cdf_border"] = "CooldownForge: arrastrar el deslizador de grosor del borde hacía desaparecer el borde en vez de engrosarlo. Cada ajuste de estilo se guardaba como un bloque, pero el editor escribe un campo cada vez — así que fijar el grosor tiraba el modo de borde que estaba al lado, y sin modo el icono se dibujaba sin borde alguno. Elegir un color hacía lo mismo, y elegir un modo reiniciaba el grosor en silencio. Esos ajustes conservan ahora los campos que no tocaste. Ninguna barra cambia por su cuenta; vuelve a fijar el valor y obtendrás lo que pediste la primera vez.",
    ["wn_335_cdf_border_paint"] = "CooldownForge: incluso después de dejar de desaparecer, el borde apenas se veía, y 1 píxel se veía exactamente igual que 4. El contorno se dibuja justo por dentro del canto del icono, y la imagen del icono lo cubría por completo — el borde se pintaba y quedaba escondido debajo, y engrosarlo solo enterraba más. La imagen ahora se detiene antes del borde y le deja sitio. Dos cosas que esperar: un icono con borde muestra su imagen ligeramente más pequeña, que es lo que cuesta un borde, y un grosor que fijaste cuando el deslizador parecía no hacer nada será de pronto visible — así que una barra que quedó en 4 se verá mucho más cargada hasta que la pongas en lo que de verdad querías. Los iconos sin borde no cambian.",
    ["wn_335_cdf_preset"] = "CooldownForge: tocar cualquier ajuste fino convertía tu barra en una barra Tomo sin decírtelo. Elegir un color de borde en una barra Net o Verre cambiaba su estilo a «Personalizado», y Personalizado no era un estilo real — así que el icono volvía a Tomo y la base que habías elegido desaparecía. Qué preajuste usa una barra y si tiene ajustes finos son ahora dos cosas distintas: cambiar de preajuste conserva tus ajustes finos encima del nuevo, y modificar un ajuste fino ya no toca el preajuste. Las barras ya guardadas como Personalizado pasan a Tomo conservando sus ajustes, que es como ya se dibujaban, así que nada cambia en pantalla.",
    ["wn_335_cdf_thickness"] = "CooldownForge: el deslizador de grosor del borde llega a 10 en vez de a 4. Cuatro era un límite razonable mientras el borde era invisible; ahora que se dibuja de verdad, ya no lo es. Ten en cuenta que el borde saca su grosor de la imagen del icono: a 10, de un icono pequeño no queda casi nada.",
    ["wn_335_cdf_target"] = "CooldownForge: una barra puede depender ahora de si tienes un objetivo, junto a las condiciones ya existentes de combate, instancia, grupo y banda, y con las mismas tres opciones — indiferente, exigirlo, exigir lo contrario. Para la barra que solo quieres ver mientras estás realmente sobre algo, o la barra de utilidad que debe apartarse en cuanto seleccionas un objetivo.",
    ["wn_335_cdf_dim"] = "CooldownForge: una barra cuya condición de visibilidad no se cumple puede ahora atenuarse en lugar de desaparecer. Elige «reducir la opacidad» en vez de «ocultar» y ajusta hasta dónde se apaga, del 5 % al 95 %. La barra atenuada sigue viva — continúa siguiendo los tiempos de reutilización en lugar de congelarse — así que «en combate = sí» con esta opción te deja fuera de combate una barra legible a media visibilidad, en vez de una que vuelve ya desactualizada. Ocultar sigue siendo lo predeterminado y nada cambia en las barras que ya tengas configuradas.",
    ["wn_335_cdf_iconwh"] = "CooldownForge: los iconos ya no tienen que ser cuadrados. El ancho y el alto tienen ahora un deslizador cada uno, de 8 a 128 píxeles, en vez de un único tamaño para ambos — iconos anchos y planos para una fila en la parte superior de la pantalla, altos y estrechos para una columna junto a tus marcos. Las barras que ya tengas hechas no se mueven: los valores nuevos empiezan sin definir, y sin definir significa «mantener el antiguo tamaño cuadrado».",
    ["wn_335_cdf_aura"] = "CooldownForge: un icono puede seguir un aumento en lugar de un tiempo de reutilización. Cambia una entrada a «aumento seguido» y se mantendrá fuera de la pantalla mientras el aumento no esté, y aparecerá con su tiempo restante y sus acumulaciones mientras esté activo — así un proc puede convivir en la misma barra con la habilidad que lo concede. También puedes indicar otro ID de aumento, para los procs que concede un hechizo y se aplican como otro. En Mítica+ el juego oculta casi todo lo que un accesorio puede leer de un aumento; eso se trata aparte más abajo.",
    ["wn_335_cdf_secret"] = "CooldownForge: un aumento seguido desaparecía en cuanto empezaba un combate y volvía en cuanto terminaba. Todas las consultas pasaban por el ID de hechizo del aumento, y en Midnight el juego oculta ese número durante el combate — medido como totalmente legible fuera de combate frente al 6,5 % dentro, con todos los aumentos seguidos desapareciendo en el mismo fotograma en que empezaba el pull. El juego sí entrega ese ID una vez, en el momento en que el aumento se aplica, junto con una referencia a esa aplicación concreta: TomoMod guarda ahora la pareja y a partir de entonces pregunta por la aplicación, algo que el juego sigue respondiendo. El tiempo restante y las acumulaciones también han vuelto en Mítica+, leídos de la misma forma — la nota anterior que decía que los aumentos seguidos funcionan allí pero sin temporizador ya no es exacta.",
    ["wn_335_cdf_aura_sources"] = "CooldownForge: los beneficios rastreados se encuentran ahora por dos caminos en lugar de cuatro. Cada uno se había añadido para cubrir un caso que se le escapaba al anterior, y nada indicaba cuál hacía realmente el trabajo — así que se midieron sobre unas 12 700 búsquedas cada uno. Dos sostenían toda la función, y cubren mitades opuestas: uno funciona durante un combate, el otro fuera de él. Los dos que no producían casi nada se han eliminado, y con ellos un barrido de todos tus beneficios que se ejecutaba en cada fotograma y para cada barra. De paso se cierra otra laguna: un beneficio que solo gana una acumulación lo comunica el juego como una actualización y no como un beneficio nuevo, así que un proc detectado así en pleno combate nunca quedaba registrado. Lo que queda es un límite del juego, mejor conocerlo que buscarlo: en combate solo nombra una parte de las auras. Un beneficio que ya está activo al empezar la pelea se rastrea con normalidad; uno aplicado en mitad de ella puede no ser identificable, y su icono permanece oculto. No hay ningún ajuste para eso, y la opción de beneficio rastreado ya lo dice allí mismo.",
    ["wn_335_cdf_viewer_source"] = "CooldownForge: un proc que salta en mitad de un combate ahora también se sigue — el límite descrito justo arriba queda en gran parte levantado. El juego se niega a decirle a un accesorio de qué beneficio se trata, pero lo lleva dibujando en tu pantalla todo el rato: la propia pantalla de beneficios seguidos de Blizzard no está sujeta a las restricciones que sí afectan a un accesorio. TomoMod lee ahora esa pantalla — si el icono está presente, el tiempo restante, el número de acumulaciones — en lugar de hacer una pregunta que el juego no responderá en combate. Nada está escrito a fuego y no se toca nada protegido: lee la misma imagen que estás viendo tú. Solo cubre los beneficios que la pantalla de beneficios seguidos de Blizzard lleva realmente: para todo lo demás, los dos métodos anteriores responden exactamente igual que antes, así que esto suma casos sin quitar ninguno. Conviene saberlo si usas el nuevo ocultado barra por barra: ocultar una barra del Cooldown Manager no te cuesta esta fuente, porque el ocultado funciona por transparencia y la barra sigue funcionando por debajo. Un detalle visual que conviene esperar en combate: donde el juego retiene los números pero sigue dibujando la cuenta atrás, TomoMod copia esa cifra en tu icono — tienes el tiempo restante como número, sin el barrido detrás, y avanza a saltos en vez de de forma continua, porque la barra se actualiza por eventos y no con un temporizador.",
    ["wn_335_cdf_aura_timer"] = "CooldownForge: un beneficio rastreado podía aparecer sin temporizador ni barrido aunque el juego hubiera indicado exactamente cuánto le quedaba. Había dos maneras de poner una cuenta atrás en el icono, y se prefería la equivocada: la que recibe un objeto de duración, que el juego devuelve con una forma distinta de la que espera la pantalla de reutilización. Lo aceptaba, no dibujaba nada y no informaba de ningún error — así que la red de seguridad pensada para atrapar ese fallo nunca saltaba, y el camino numérico, que sí habría funcionado, nunca se alcanzaba. Ahora se usan primero los números legibles, y el objeto solo cuando el juego se niega a dar los números. Si tus beneficios rastreados salían como un icono pelado, recuperan su temporizador y sus acumulaciones.",
    ["wn_335_cdf_glow_aura"] = "CooldownForge: la condición de brillo «mientras un beneficio esté activo en ti» se apagaba durante todos los combates, y nadie lo había relacionado con los beneficios rastreados. Preguntaba al juego por tu beneficio de la misma manera que lo hacían al principio los beneficios rastreados — la manera que deja de responder en cuanto empieza el combate — así que el brillo simplemente se detenía, lo que parece un brillo mal configurado más que un fallo. Ahora encuentra los beneficios exactamente igual que los iconos de beneficio rastreado, de modo que ambos ya no pueden discrepar sobre lo que llevas.",
    ["wn_335_microbar"] = "Nuevo — Micro Barra: la pequeña fila de botones de menú de Blizzard se convierte en una barra tuya. Elige qué botones aparecen y en qué orden, en horizontal o en vertical, cuántos por línea, su tamaño, su separación, su escala y su opacidad, y colócala donde quieras desde el panel de Movedores. Puede quedarse siempre en pantalla, aparecer al pasar el ratón, o aparecer al pasar el ratón y mantenerse durante el combate. Los iconos pueden tomar el color de tu clase, un color que elijas o su aspecto original, con desaturación opcional y un zoom bajo el cursor. Cada botón se limita a reenviar tu clic al de Blizzard: así todo sigue funcionando en combate y nada se rompe cuando se añade un panel nuevo al juego. Los originales también siguen funcionando por debajo, de modo que sus avisos, sus estados en gris y sus atajos pueden reflejarse en tus botones — con cuatro estilos de brillo de aviso a elegir, atenuación de lo que no está disponible, y el atajo dibujado sobre el icono.",
    ["wn_335_cdf_aura_gate"] = "CooldownForge: un aumento seguido ya no tiene que ser un hechizo que puedas lanzar. Antes de mostrar icono alguno, la barra comprueba que la entrada te corresponde, y para un hechizo consultaba tu libro de hechizos — lo correcto para un tiempo de reutilización y lo equivocado para un aumento. Los aumentos de proc te los concede un talento o te los aplica otro hechizo, así que tu libro de hechizos dice que no los tienes, y la entrada quedaba descartada antes de que nada mirase si el aumento estaba realmente activo. El icono no aparecía nunca — que es para lo que sirven los aumentos seguidos, en su mayor parte. Un aumento seguido se juzga ahora por el aumento.",
    ["wn_335_cdf_aura_link"] = "CooldownForge: seguir un proc ya no obliga a rastrear el ID del propio aumento. Una habilidad y el aumento que concede casi nunca comparten ID, así que introducir la habilidad — lo evidente — vigilaba un aumento que nadie tiene jamás, y el icono simplemente se quedaba fuera de la pantalla. Una entrada prueba ahora también lo que el juego vincula al ID que escribiste: el Cooldown Manager de Blizzard ya resuelve lo mismo para su propio visor de aumentos seguidos, y TomoMod lee esa misma respuesta. Nada está fijado en el código, así que sigue por su cuenta un parche que redirige un proc o un talento que lo cambia. El campo opcional de ID de aumento sigue funcionando y sigue teniendo prioridad, para los casos que el juego no vincula.",
    ["wn_335_cds_reorder"] = "Cooldown Studio: las entradas de una barra pueden moverse arriba y abajo. Reordenar tus iconos obligaba a quitar una entrada, volver a añadirla al final y rehacer todo lo que venía detrás. Si el panel de opciones está abierto sobre la entrada que mueves, la sigue en vez de quedarse en la posición — antes acababa editando la que hubiera ocupado su lugar.",
    ["wn_335_mplus_teleport_override"] = "Mítica+: un teletransporte de mazmorra presente en tu libro de hechizos podía seguir apareciendo como no aprendido — la fila en gris, la descripción diciendo que no estaba disponible, el clic sin efecto. Cuando una mazmorra vuelve en una temporada posterior, Blizzard reemite su teletransporte como un hechizo distinto: el de Skyreach se lanza ahora como «Voie des cieux», y no el hechizo de Warlords que figura en la tabla de TomoMod. La comprobación solo preguntaba por el hechizo listado, así que tener el actual era indistinguible de no tener ninguno. Ahora también le pregunta al juego qué hechizo sustituye al que conoce, y acepta cualquiera de los dos — por número de hechizo y no por nombre, de modo que funciona sea cual sea el idioma de tu cliente, y seguirá a una futura temporada que reasigne un teletransporte sin necesidad de una actualización.",
    ["wn_335_ab_taint"] = "Barras de acción: la opción «mostrar los espacios de botón vacíos» era el origen de una ráfaga de errores de acción bloqueada en los botones de la barra inferior izquierda — errores que el juego achacaba al accesorio que estuviera funcionando en ese momento, lo que últimamente hacía parecer que la culpa era de Cooldown Studio. Mostrar los espacios vacíos se hacía escribiendo en el estado interno de los botones de Blizzard y forzando su aparición, algo que el juego después se niega a tocar. La opción usa ahora el propio ajuste del juego «mostrar siempre las barras de acción», y las barras que no deben mostrar sus vacíos se vuelven invisibles y no clicables en su lugar. Blizzard conserva el control de sus botones. Dos cosas a tener en cuenta: ese ajuste es global, así que se activa en cuanto una sola de tus barras quiere sus espacios vacíos, y si lo habías activado tú en las opciones de Blizzard, se desactivará en cuanto ninguna barra de TomoMod lo necesite. Soltar un hechizo en un espacio vacío funciona exactamente igual que antes.",
    ["wn_335_cdm_viewers"] = "Cooldowns: las cuatro barras del Cooldown Manager de Blizzard ya se pueden ocultar una por una, desde el panel de Cooldowns junto al botón del Cooldown Studio — Essential, Utility y las dos pantallas de seguimiento de beneficios tienen cada una su casilla. Marcar una quita esa barra de la pantalla y del modo de colocación de TomoMod, y deja las otras tres donde están. Sustituye a una casilla única que no ocultaba nada: se limitaba a detener el reestilizado de TomoMod sobre esas barras, que seguían en pantalla con el aspecto propio de Blizzard — una casilla llamada «ocultar las barras del Cooldown Manager» que las hacía más visibles en lugar de menos. Una barra oculta se vuelve invisible y no clicable, no se elimina: sigue siendo la barra de Blizzard, sigue funcionando por debajo, y si existe o no se decide todavía en el modo edición de Blizzard. Desmarcarla la devuelve exactamente donde la habías colocado. El interruptor de CD y Recursos no ha cambiado y responde a otra pregunta — si TomoMod reestiliza estas barras, no cuáles quieres ver. Además ahora funcionan juntos: ocultar una barra sigue surtiendo efecto cuando el propio módulo Cooldown Manager está desactivado, que era la única combinación en la que la casilla se guardaba y no se aplicaba a nada — y es justo lo que va a probar quien quiera quitarse estas barras de encima.",
    ["wn_335_cdf_entry_spec"] = "CooldownForge: la especialización de una entrada solo podía elegirse en el momento de añadirla. Después, nada en ninguna parte permitía cambiarla — un icono añadido en la especialización equivocada, o añadido antes de que decidieras restringirlo a una sola, había que borrarlo y volver a añadirlo, con lo que además perdía su sitio en la barra. El desplegable está ahora en la propia entrada, tanto en Cooldown Studio como en la página de ajustes de Cooldowns.",
    ["wn_335_scrollbar_click"] = "Ajustes: la barra de desplazamiento de la ventana de ajustes ya se ve y se puede usar. Eran cinco píxeles de gris oscuro sobre un panel oscuro — casi imposible de acertar, y ya de por sí difícil de notar, así que la rueda era en la práctica la única forma de bajar por una página larga. Hacer clic en el raíl por encima o por debajo del tirador salta ahora casi una pantalla en esa dirección, y el tirador se puede agarrar sin tener que apuntarlo con precisión. También cambia de aspecto, a propósito: algo más ancha, en un gris más claro y con una línea oscura fina en su borde interior para que destaque del panel. Los cuadros de texto de las cadenas de importación y exportación llevan la misma barra, y ahora coinciden. Esto vale para todas las páginas de los ajustes, no solo una.",
    ["wn_335_cds_tabjump"] = "Cooldown Studio: cambiar casi cualquier cosa te lanzaba a otra pestaña. Editar el estilo de un icono te dejaba en Compartir; marcar una condición de visibilidad te dejaba en Disposición. El editor se reconstruye tras casi cada cambio y reabría la pestaña que tenía memorizada — pero solo memorizaba una pestaña la primerísima vez que se construía, así que se quedaba clavado en la última que hubieras abierto por primera vez, y volver a una pestaña ya visitada nunca lo actualizaba. Ahora sigue la pestaña en la que realmente estás.",

    -- =====================
    -- 3.3.4 — Novedades
    -- =====================
    ["wn_334_studio_reasons"] = "Cooldown Studio: el botón «Abrir el Cooldown Studio» podía no hacer absolutamente nada. Todos los motivos posibles por los que el editor no lograba cargarse se anunciaban con el mismo mensaje — «no instalado» — incluido el más habitual con diferencia: está instalado y simplemente sin marcar en tu lista de accesorios. Ahora cada motivo dice cuál es y qué hacer al respecto.",
    ["wn_334_studio_enable"] = "Cooldown Studio: si el único problema es que está sin marcar en la lista de accesorios, pulsar el botón lo marca y abre el editor. Cuando el juego exige antes una recarga, lo dice en lugar de mandarte a buscar el ajuste por tu cuenta.",
    ["wn_334_studio_preflight"] = "Cooldown Studio: la tarjeta de la pestaña Cooldowns te avisa de que el editor no puede abrirse antes de que pulses, no después. El botón sigue siendo pulsable a propósito: en un accesorio sin marcar, pulsarlo es justamente lo que arregla la situación.",
    ["wn_334_studio_init"] = "Cooldown Studio: un editor que se cargaba pero no conseguía arrancar se tragaba tu clic sin decir nada. Ahora indica que se ha cargado pero no ha podido inicializarse, y por qué.",
    ["wn_334_studio_toc"] = "Cooldown Studio: el subaccesorio muestra ya el icono de TomoMod, una categoría y el número de versión real del accesorio en tu lista. Seguía declarando 1.0.0 y sin icono, lo que le daba aspecto de ser el accesorio de otra persona que casualmente comparte el nombre.",
    ["wn_334_package_builder"] = "Empaquetado: la descarga la genera ahora un script que se niega a producirla si el Cooldown Studio acaba dentro de la carpeta TomoMod en lugar de al lado. WoW solo mira el primer nivel de la carpeta AddOns, así que un Studio guardado un nivel más abajo es un Studio que nadie ve en su lista de accesorios — que es exactamente la situación que la mitad de las correcciones anteriores sirven para diagnosticar.",
    ["wn_334_diag_export"] = "Diagnóstico: la ventana de exportación te pedía copiar el informe y luego ponía la dirección del rastreador en su título — una dirección que solo podías llevarte tirando el informe que acababas de copiar. Ahora alterna entre el informe y el enlace, te dice cuál de los dos acaba de entrar en el portapapeles y muestra la dirección en texto claro en pantalla para que puedas simplemente leerla.",
    ["wn_334_diag_reminder"] = "Diagnóstico: la ventana indica ahora que tu informe está guardado y puede reabrirse en cualquier momento con /tmdiag tracker, así que llevarte el enlace primero no te cuesta nada. Al cerrarla también se imprime la dirección en el chat, una vez por sesión, por si la cerraste demasiado rápido.",
    ["wn_334_presets_roles"] = "Presets: los presets Tanque, Sanador y DPS escribían solo tres o cuatro ajustes cada uno y tomaban todo lo demás de la base común — tres arquetipos que eran la misma configuración con nombres distintos. Ahora cada uno escribe una configuración de rol completa en los marcos de grupo y banda, las placas de nombre, las auras del objetivo, los recursos, las reutilizaciones y las barras de lanzamiento: placas anchas coloreadas por amenaza y amenaza numérica para los tanques, marcos mucho más grandes con HoTs, disipaciones y escudos para los sanadores, barras de recurso más altas y solo tus propios perjuicios para el daño.",
    ["wn_334_presets_reset"] = "Presets: pasar de uno a otro conservaba los ajustes del anterior. Un preset solo escribía sus propios cambios, así que todo lo que no mencionaba se quedaba tal como lo había dejado el último — pasar de Tanque a Sanador te hacía sanar con placas en modo tanque. La base común contiene ahora un valor para cada ajuste que un preset pueda tocar y se escribe primero siempre: aplicar un preset da el mismo resultado sea cual sea el que hubiera antes.",
    ["wn_334_presets_cards"] = "Inicio: los presets son ahora tarjetas en lugar de cuatro botones de colores que solo llevaban un nombre. Cada una muestra su icono de rol, su lema y tres puntos sobre lo que cambia realmente, con la descripción completa al pasar el ratón — y el que estás usando aparece marcado como «Activo», algo que ese panel no indicaba en ninguna parte.",
    ["wn_334_role_badges"] = "Ajustes: las secciones que importan a un rol concreto llevan ahora un pequeño icono de tanque, sanador o daño en su encabezado — HoTs y disipaciones, reutilizaciones defensivas, modo tanque, seguimiento de interrupciones, texto de amenaza y demás. Al pasar el ratón por los iconos se nombran los roles.",
    ["wn_334_role_filter"] = "Ajustes: se ha añadido una barra de enfoque de rol en la parte superior de la barra lateral — Todos, Tanque, Sanador, DPS. Elegir uno mantiene a plena luz los ajustes de ese rol y atenúa los demás. Atenúa en lugar de ocultar a propósito: una opción cuya ubicación ya conoces sigue exactamente donde la dejaste, sea cual sea el enfoque activo. Tu elección se conserva entre sesiones.",
    ["wn_334_chat_history_settings"] = "Historial del chat: lo único que podías hacer con él era activarlo. Ahora tiene su propia sección — cuánto tiempo se conservan los mensajes (de 1 hora a 3 días, o sin límite), cuántas líneas se almacenan (10 a 500) y una marca de sesión tras las líneas restauradas, para que todo lo que aparezca debajo sea claramente de la sesión actual. El límite de almacenamiento además estaba desviado en uno: anunciaba 128 líneas y guardaba 127.",
    ["wn_334_chat_history_delay"] = "Historial del chat: las líneas restauradas se imprimían justo en el momento en que los mensajes de carga de addons y los errores de Lua llegan al chat, sepultándolos bajo una página entera de repetición. El historial ahora espera unos segundos antes de aparecer — ajustable, o cero para recuperar el comportamiento anterior.",
    ["wn_334_chat_history_channels"] = "Historial del chat: qué canales se conservan — susurros, hermandad, oficial, grupo, banda, instancia, canales, decir, gritar, emotes — era un ajuste desde que la función existe y no aparecía en ninguna parte de la interfaz. Ya está en el panel. Un canal desmarcado no se registra en absoluto, no es que solo se omita al restaurar: volver a marcarlo no recupera lo que pasó mientras estaba apagado.",
    ["wn_334_chat_history_clear"] = "Historial del chat: ahora hay un botón para borrarlo todo, tras una confirmación, y desactivar la función borra lo que ya estaba guardado en lugar de dejar cada línea en tus variables guardadas. El panel lo indica antes de que desmarques la casilla — junto con el hecho de que el historial se guarda para toda la cuenta y por tanto lo comparten todos tus personajes.",
    ["wn_334_roles_guides"] = "Roles: una nueva categoría Roles, con una página guía para tanquear, sanar y hacer daño. Cada una explica lo que de verdad importa en ese rol, y cada punto lleva un botón que abre el panel donde está el ajuste y lo resalta. La página también aplica el preset del rol y cambia el enfoque de rol de la barra lateral con un clic.",
    ["wn_334_search_nested_tabs"] = "Búsqueda de la configuración: un resultado situado en una pestaña anidada — los HoTs de los marcos de banda, los colores de las barras de recurso, cualquier cosa que un panel guarde tras su propia segunda fila de pestañas — abría la categoría correcta y luego aterrizaba en su primera pestaña, no en la que contenía lo buscado. El índice solo guardaba el nombre de la pestaña más interna, que la barra exterior nunca podía reconocer. Ahora registra un nombre por nivel, y cada barra de pestañas lee el suyo.",
    ["wn_334_search_index_all_tabs"] = "Búsqueda de la configuración: la mayoría de los ajustes ni siquiera estaba en el índice. Las páginas que nunca has abierto se construyen una vez, fuera de pantalla, para que la búsqueda pueda encontrarlas — pero un panel solo construye su primera pestaña, así que todo lo que está detrás de una segunda o tercera subpestaña, es decir el grueso de la interfaz, no se podía encontrar buscándolo. Ahora se recorren todas las pestañas. Eso supone construir mucho más, así que el trabajo se hace en segundo plano en tramos de unos pocos milisegundos en lugar de congelar el juego en tu primera búsqueda, y una lista de resultados ya visible se actualiza sola al terminar.",
    ["wn_334_search_index_duplicates"] = "Búsqueda de la configuración: los paneles que reutilizan una misma página en varias pestañas — cada unidad de barra de lanzamiento, cada marco de unidad — se reducían a un único resultado. El índice solo guardaba el nombre de la pestaña más interna, de modo que la barra del objetivo y la del foco escribían la misma entrada sobre la misma sección, y todas las copias salvo la primera desaparecían. Las entradas llevan ahora la ruta completa, y las secciones de cada unidad se listan por separado.",
    ["wn_334_roles_deeplink"] = "Roles: los botones de las páginas guía abrían la categoría correcta y luego te dejaban en la pestaña que hubieras usado la última vez. Buscaban su ajuste en el índice de búsqueda, y esos ajustes — HoTs de los marcos de banda, defensivos de grupo, modo tanque — eran justamente los que le faltaban al índice. Cada botón nombra ahora su propia ruta, pestaña a pestaña: aterriza en la página correcta y resalta la sección, tanto en un cliente recién arrancado como sobre lo que estuvieras mirando antes.",
    ["wn_334_cr_detection"] = "Recordatorio de clase: leía la barra de posturas por posición. Felino era la casilla 2, Oso la 1, Lechúcico lunar la 4 — pero dónde se coloca una forma en esa barra depende de tus talentos. En cuanto cambiaba, el recordatorio comparaba tu forma real con una casilla que no tenía nada que ver: te avisaba de una forma ausente mientras estabas en ella, o callaba mientras estabas fuera. Ahora las formas se reconocen por hechizo. Los guerreros recuperan sus tres posturas, una por especialización, en vez de una entrada que cubría tres casillas en todas las especializaciones. Y las auras de paladín se buscaban entre las formas, donde jamás iban a aparecer — son buffs, y se comprueban como tales.",
    ["wn_334_cr_false"] = "Recordatorio de clase: algunos avisos no había forma de apagarlos. El evocador seguía un único buff de Bendición del Bronce, y ese hechizo aplica uno distinto a cada clase — así que a doce clases de trece se les decía que les faltaba un buff que llevaban puesto, mientras el módulo estuviera activo. Lo mismo con las versiones de talento de Marca de lo Salvaje, Intelecto Arcano, Forma de lechúcico lunar y Forma de las Sombras: solo se conocía la versión base, de modo que quien jugaba la variante recibía avisos por un buff que ya tenía.",
    ["wn_334_cr_icons"] = "Recordatorio de clase: era una línea de texto pulsante en el centro de la pantalla nombrando lo que faltaba. Ahora es una fila de iconos, uno por cada buff, forma, postura o aura que falte, y fuera de combate un clic izquierdo lo lanza en vez de obligarte a leer su nombre e ir a buscarlo a una barra. El clic central descarta un aviso hasta la próxima pantalla de carga, para el buff que has decidido no llevar hoy. En combate nada es clicable, a propósito: una fila que siguiera armada mentiría sobre lo que hace pulsarla.",
    ["wn_334_cr_options"] = "Recordatorio de clase: tamaño de icono, espaciado, escala de la fila, opacidad, la etiqueta y su tamaño, y un resplandor con su propio color. Los dos deslizadores de posición han desaparecido — la fila se coloca con el movedor, como todo lo que se mueve, y tiene su propia entrada en el panel de Movimiento. Si la habías desplazado con los deslizadores, esa posición se conserva una vez.",
    ["wn_334_cr_panel"] = "Recordatorio de clase: la página de ajustes se abre con una vista previa viva de la fila, dibujada por el propio módulo, así que cada deslizador mueve justo lo que estás mirando. Al hacer clic en un icono llegas a su interruptor, en su etiqueta a las opciones de etiqueta, en el espacio de alrededor a los deslizadores de tamaño. Y la lista de clases compatibles — un párrafo de texto por clase — es ahora una rejilla, una casilla por buff o forma seguidos, coloreada por clase, cada una un interruptor que puedes apagar para aquello sobre lo que prefieras no recibir avisos.",
    ["wn_334_cr_enchants"] = "Recordatorio de clase: los encantamientos de arma no se seguían en absoluto. Lengua de fuego, furia del viento, tierra viva, guardia del invocamareas y custodia de golpe de trueno tienen cada uno su recordatorio, y los dos ritos del Forjaluz comparten uno, ya que se excluyen mutuamente y basta con tener cualquiera de ellos. No son auras: el juego nunca los anunciaba como anuncia un aumento — ahora desaparecen en cuanto aplicas uno, en vez de esperar a una actualización que no tiene nada que ver.",
    ["wn_334_cr_poisons"] = "Recordatorio de clase: los venenos de pícaro, un recordatorio por categoría en vez de por veneno — letal y no letal. Lo que importa es que las ranuras estén llenas: se cuenta cuántos venenos de esa categoría están activos frente a cuántos puedes aplicar realmente, uno o dos con Hojas templadas en dragón. Ninguna lista de builds que mantener, y nada que reconfigurar al cambiar de talentos.",
    ["wn_334_cr_shields"] = "Recordatorio de clase: los escudos de chamán se siguen, y Órbita elemental se tiene en cuenta en vez de ignorarse. Con el talento llevas Escudo de tierra sobre ti y uno de los otros dos, así que se comprueban ambos; sin él, basta con un escudo cualquiera. El recordatorio nombra la categoría y su icono apunta al escudo correcto para tu especialización — agua para Restauración, relámpagos en el resto.",
    ["wn_334_cr_context"] = "Recordatorio de clase: ahora eliges dónde aparece — en todas partes, solo en mazmorras y bandas, o solo en grupo. Está oculto en ciudades y posadas de forma predeterminada, porque es justo donde vas a reaplicarlo todo, y se calla mientras estás muerto, en un vehículo o volando en montura: estados en los que no puedes pulsar nada de la fila.",
    ["wn_334_cr_group"] = "Recordatorio de clase: también puede vigilar al grupo. Activa «avisar también cuando a un miembro del grupo le falta un aumento» y un aumento de grupo que tú llevas seguirá lanzando su aviso mientras alguien a rango no lo tenga — el caso que siempre se le escapaba, porque tenerlo tú no dice nada del resto del grupo. Solo cuentan los miembros a los que la estadística les sirve, y solo fuera de combate: las auras de otro jugador no se pueden leer en pleno combate, y adivinar dejaría un aviso en pantalla durante todo el pull. Desactivado por defecto, porque vigilar las auras de todos no sale gratis.",
    ["wn_334_cr_perf"] = "Recordatorio de clase: reexaminaba tus auras y tu barra de posturas una vez por segundo, indefinidamente, hubiera cambiado algo o no. El juego ya anuncia un buff ganado, perdido o caducado, y la barra de posturas tiene sus propios eventos: ese sondeo no servía de nada. Ahora reacciona a eventos, y además detecta un cambio de talentos o de libro de hechizos, que es justo cuando el conjunto de formas afectadas cambia de verdad.",
    ["wn_334_uf_preview_engine"] = "Marcos de unidad: la vista previa de los ajustes era una maqueta. Dibujaba sus propias barras falsas a partir de los mismos valores pero con su propio código, así que podía discrepar de lo que obtenías en el juego — y discrepaba. Ahora la construyen las mismas funciones que construyen tus marcos reales: textura de barras, fuentes, bordes, la barra de información, los desplazamientos de elementos, la rejilla de auras, los beneficios enemigos y la amenaza provienen todos del motor real, y la vista previa ya no puede desviarse.",
    ["wn_334_uf_preview_live"] = "Marcos de unidad: la vista previa muestra tus unidades reales. Cuando la unidad existe — tu objetivo, tu foco, tu mascota — los marcos se alimentan con datos reales y se marcan como REAL; si no, recurren a valores simulados marcados como SIM. También hay un conmutador Ajustar / 1:1 para revisar los marcos a su tamaño real en píxeles en lugar de en la tira reducida.",
    ["wn_334_uf_texture_live"] = "Marcos de unidad: cambiar la textura de las barras no hacía nada hasta recargar — solo se leía al crear el marco. Lo mismo con los números de duración de las auras. Ambos se aplican sobre la marcha ahora, en tus marcos reales y no solo en la vista previa.",
    ["wn_334_tmkeys"] = "Mítica+: /tm keys abre el marcador sobre tu grupo real — el nombre, la clase, la puntuación M+ y la piedra angular que lleva cada uno. Hasta ahora ese marcador solo aparecía por su cuenta al terminar una carrera, y el único comando que lo abría a mano mostraba datos de ejemplo, no gente de verdad. El momento de decidir qué llave correr era justo aquel en el que no podías consultarlo. Funciona fuera de la mazmorra, que es donde hace falta.",
    ["wn_334_score_roleicon"] = "Mítica+: cada fila del marcador muestra ahora un icono de rol junto al icono de especialización, con los mismos colores que los presets de rol y las insignias de los ajustes. La especialización dice qué ha traído alguien, el rol dice qué hace con ello, y una lista de llaves que se lee antes de pullear quiere las dos cosas.",
    ["wn_334_score_spec"] = "Mítica+: tu propia especialización faltaba en tu fila del marcador — el juego no la devuelve por la misma llamada que usa para los demás. Ahora se lee directamente. Los jugadores que comparten rol también salían en un orden distinto cada vez que se abría el marcador fuera de una carrera, ya que la cifra de daño que normalmente los separa allí vale cero para todos; los empates se resuelven ahora por nivel de llave, luego puntuación, luego nombre.",
    ["wn_334_mplus_teleports"] = "Mítica+: los teletransportes de mazmorra que habías conseguido se mostraban como no aprendidos. El panel y el marcador atenuaban la mazmorra, la información emergente decía que el teletransporte no estaba disponible, y al pulsar la fila aparecía «no aprendido» sin lanzar nada. La comprobación que usaba solo informa de los hechizos que te concede tu clase o tu mascota, y los teletransportes de mazmorra vienen de logros — así que respondía que no a todos y cada uno, hubiera lo que hubiera en tu libro de hechizos. Reportado con Cielo Escarpado, y afectaba a la lista entera. Ahora los teletransportes funcionan desde el panel.",
    ["wn_334_delete_confirm"] = "Confirmación de borrado: la función que escribe la palabra de confirmación por ti seguía buscando una pieza de esa ventana que Blizzard eliminó en la 11.2, y solo funcionaba gracias a un recurso de reserva que adivina el nombre interno de la ventana. Ahora le pide el campo de texto al juego por la vía admitida, con las rutas antiguas detrás — así que seguirá rellenando la casilla haga lo que haga Blizzard con esa ventana a continuación.",
    ["wn_334_friends_removed"] = "Contactos: se ha eliminado el skin de la ventana de contactos, junto con su pestaña en los ajustes. Blizzard va a reconstruir esa ventana en la 12.1, y el skin funcionaba yendo a buscar varias decenas de sus piezas una a una, por su nombre — nombres que esa reconstrucción puede mover o renombrar a su antojo. Eso no envejece con suavidad: el día del parche queda una ventana a medio desvestir, en tu pantalla y no en la nuestra. El skin venía desactivado por defecto; si lo tenías activado, la ventana recupera sin más el aspecto propio de Blizzard. El botón Contactos de la barra lateral del chat no se ve afectado.",

    -- =====================
    -- QOL: Companion Status (recordatorio de mascota)
